import { Book } from "@/lib/types";

export const _1kings: Book = {
  id: "1kings",
  name: "1. Könige",
  shortName: "1Kön",
  testament: "old",
  introduction: `Was Reich und Religion zerstört\nUrsprünglich waren beide Königsbücher ein einziges Buch auf einer langen Schriftrolle. Erst nach der Übersetzung des Alten Testaments aus dem Hebräischen ins Griechische, in der so genannten Septuaginta, haben die Übersetzer es aus praktischen Gründen in zwei Schriftrollen geteilt. **Das Buch von den Königen** ist die Fortsetzung der Geschichte, die mit den Samuelbüchern begann. Die beiden Königsbücher verzeichnen die Regierungen aller Könige von Israel und Juda, außer der von Saul. Sie zeigen die drei großen Perioden der Königsgeschichte: das vereinte Königreich, das in Juda und Israel aufgeteilte Reich und das überlebende Reich Juda bis zu seiner Deportation in die Gefangenschaft nach Babylon. Die Königsbücher sind zwischen den Jahren 560 und 537 v.Chr. vollendet worden, wahrscheinlich schon kurz nach 560. Die Befreiung aus der babylonischen Gefangenschaft 538 v.Chr. wird jedenfalls nicht mehr erwähnt. Ihr inspirierter Verfasser lebte wahrscheinlich im Exil in Babylonien. Sein Name wird uns aber nicht genannt. Er arbeitete viele Quellen ein, wie sie zum Beispiel in 1. Könige 11,41 und 14,19 erwähnt werden.\n****Wie Davids Sohn Salomo König wird, sein Reich zu einmaliger Größe führt, aber schon den Keim zur Spaltung und zum Abfall von Gott legt.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "König David war sehr alt geworden. Obwohl man ihn in Decken hüllte, wurde es ihm nicht warm.", heading: "1-11: Das geeinte Reich unter Salomo\nSalomos Regierungsantritt (1-4)\nAdonija will an die Macht" },
      { number: 2, text: "Da sagten seine Diener zu ihm: \"Gestatte uns doch, für dich, unseren Herrn und König, ein junges, unberührtes Mädchen zu suchen, das dich bedient und pflegt. Wenn sie dann in deinen Armen schläft, wird es dir, unserm Herrn und König, wieder warm werden.\"" },
      { number: 3, text: "So suchten sie in ganz Israel nach einem schönen Mädchen. Sie fanden Abischag aus Schunem* und brachten sie zum König.", footnotes: ["Schunem lag 15 km östlich von Megiddo am Fuß des Berges More. Heute: Solem."] },
      { number: 4, text: "Das Mädchen war außerordentlich schön. Sie wurde Pflegerin des Königs und bediente ihn. Der König hatte jedoch keinen sexuellen Verkehr mit ihr." },
      { number: 5, text: "Damals wurde Adonija, der Sohn von Davids Frau Haggit, überheblich und erklärte: \"Ich bin der künftige König!\" Dann schaffte er sich Wagen und Pferde an und legte sich eine Leibwache von fünfzig Mann zu, die vor ihm her liefen." },
      { number: 6, text: "Sein Vater David hatte ihm sein Leben lang nie Vorhaltungen gemacht und ihn nie wegen irgendetwas zur Rede gestellt. Adonija war ein stattlicher Mann und nach Abschalom der Älteste der Davidsöhne." },
      { number: 7, text: "Er hatte mit Joab Ben-Zeruja* und dem Priester Abjatar gesprochen und sie für sich gewinnen können.", footnotes: ["Zeruja war die Halbschwester Davids."] },
      { number: 8, text: "Den Priester Zadok und Benaja Ben-Jojada* konnte er aber nicht auf seine Seite ziehen, auch den Propheten Natan nicht und auch nicht Schimi und Rei und die Elitetruppe Davids.", footnotes: ["Benaja war Befehlshaber der königlichen Leibwache (2. Samuel 20,23)."] },
      { number: 9, text: "Nun veranstaltete Adonija am Schlangenstein bei der Rogelquelle* ein Opfermahl. Er ließ Schafe, Rinder und Mastkälber schlachten und lud alle seine Brüder, die Königssöhne, ein, dazu alle Männer von Juda, die im Dienst des Königs standen,", footnotes: ["Die Rogelquelle liegt 1,5 km südlich von Jerusalem im Kidrontal."] },
      { number: 10, text: "nicht aber den Propheten Natan, auch nicht Benaja und die Elitetruppe und seinen Bruder Salomo." },
      { number: 11, text: "Da ging Natan zu Batseba, der Mutter Salomos, und sagte: \"Hast du nicht gehört, dass Adonija, der Sohn der Haggit, sich zum König gemacht hat? Und David, unser Herr, weiß nichts davon." },
      { number: 12, text: "Komm, ich will dir einen Rat geben, damit du dein Leben und das deines Sohnes Salomo retten kannst." },
      { number: 13, text: "Geh zum König David und sag zu ihm: 'Mein Herr und König, hast du nicht selbst deiner Magd geschworen: Dein Sohn Salomo und kein anderer soll mir auf dem Königsthron folgen! Warum ist jetzt aber Adonija König geworden?'" },
      { number: 14, text: "Und während du noch mit ihm sprichst, werde ich selbst kommen und deine Worte bekräftigen.\"" },
      { number: 15, text: "Da ging Batseba ins Gemach des Königs. Dieser war sehr alt geworden, und Abischag aus Schunem bediente ihn." },
      { number: 16, text: "Batseba verneigte sich vor dem König und warf sich dann ganz vor ihm nieder. \"Was hast du?\", fragte der König." },
      { number: 17, text: "\"Mein Herr\", erwiderte sie, \"du hast doch deiner Magd bei Jahwe, deinem Gott, geschworen: 'Dein Sohn Salomo und kein anderer soll mir auf dem Königsthron folgen!'" },
      { number: 18, text: "Aber sieh doch, jetzt ist Adonija König geworden – und du, mein Herr und König, weißt nicht einmal davon!" },
      { number: 19, text: "Er hat eine Menge Rinder, Mastkälber und Schafe schlachten lassen und alle Königssöhne dazu eingeladen, auch den Priester Abjatar und den Heerführer Joab, nur deinen Diener Salomo nicht." },
      { number: 20, text: "Ganz Israel blickt jetzt auf dich, mein Herr und König. Sie warten darauf, dass du ihnen bekannt gibst, wer dir auf dem Königsthron folgen soll." },
      { number: 21, text: "Sonst werden ich und mein Sohn es büßen müssen, wenn du eines Tages nicht mehr lebst.\"" },
      { number: 22, text: "Während sie noch mit ihm sprach, kam der Prophet Natan in den Palast." },
      { number: 23, text: "Man meldete dem König: \"Der Prophet Natan ist da!\" Er trat ein und warf sich vor dem König nieder, sodass sein Gesicht den Boden berührte." },
      { number: 24, text: "\"Mein Herr und König\", sagte er, \"du hast wohl angeordnet, dass Adonija der Nachfolger auf deinem Thron werden soll?" },
      { number: 25, text: "Denn er ist heute hinuntergegangen und hat eine Menge Rinder, Mastkälber und Schafe schlachten lassen. Er hat alle Königssöhne eingeladen, die Truppenführer und den Priester Abjatar. Sie essen und trinken als seine Gäste und rufen: 'Es lebe König Adonija!'" },
      { number: 26, text: "Aber mich, deinen Diener, den Priester Zadok, Benaja Ben-Jojada und deinen Diener Salomo hat er nicht eingeladen." },
      { number: 27, text: "Wenn diese Sache wirklich von meinem Herrn, dem König, ausgegangen ist, dann hast du deine treuen Diener also nicht wissen lassen, wer dir auf dem Königsthron nachfolgen soll.\"" },
      { number: 28, text: "\"Ruft mir Batseba!\", befahl König David. Sie kam herein und trat vor ihn hin.", heading: "Salomo wird zum König gesalbt" },
      { number: 29, text: "Da schwor der König und sagte: \"So wahr Jahwe lebt, der mich aus jeder Not gerettet hat:" },
      { number: 30, text: "Ja, ich habe dir bei Jahwe, dem Gott Israels, geschworen, dass dein Sohn Salomo nach mir König sein soll, dass er und kein anderer mein Nachfolger auf dem Thron wird. Und so werde ich es heute wahr machen.\"" },
      { number: 31, text: "Da verneigte sich Batseba vor dem König, dass ihr Gesicht den Boden berührte, und sagte: \"Lang lebe mein Herr, der König David!\"" },
      { number: 32, text: "Dann sagte David: \"Ruft mir den Priester Zadok, den Propheten Natan und Benaja Ben-Jojada!\" Als sie hereingekommen waren," },
      { number: 33, text: "befahl er ihnen: \"Lasst meinen Sohn Salomo auf meiner eigenen Mauleselin reiten; nehmt meine Leibgarde und geleitet ihn zur Gihonquelle* hinunter!", footnotes: ["Die Gihonquelle war die bedeutendste Wasserquelle für die Stadt Jerusalem. Sie lag genau östlich der Stadt im Kidrontal."] },
      { number: 34, text: "Der Priester Zadok und der Prophet Natan sollen ihn dort zum König über Israel salben*. Dann sollt ihr das Signalhorn* blasen und rufen: 'Es lebe König Salomo!'", footnotes: ["salben. Bei einer zeremoniellen Salbung wurde der Person kostbares duftendes Öl über den Kopf gegossen. In diesem Fall war es die Krönung zum König.", "Das Signalhorn (Hebräisch: Schofar) war aus den gewundenen Hörnern des männlichen Fettschwanzschafes hergestellt und brachte einen dumpfen, durchdringenden Ton hervor."] },
      { number: 35, text: "Anschließend zieht ihr hinter ihm her wieder herauf. Er soll hereinkommen und sich auf meinen Thron setzen. Er und kein anderer soll an meiner Stelle König sein. Ihn habe ich zum Herrscher über Israel und Juda bestimmt.\"" },
      { number: 36, text: "\"Amen\", sagte Benaja Ben-Jojada, \"so bestätige es Jahwe, der Gott meines Königs und Herrn!" },
      { number: 37, text: "So wie Jahwe meinem Herrn und König zur Seite stand, möge er auch Salomo zur Seite stehen und ihn noch größer machen als meinen Herrn und König David!\"" },
      { number: 38, text: "Zadok, Natan und Benaja ließen Salomo auf der Mauleselin des Königs reiten und gaben ihm mit der königlichen Leibgarde* das Geleit zur Gihonquelle.", footnotes: ["Leibwache. Wörtlich: den Kretern und Pletern. Es waren ausländische Söldner, hauptsächlich Philister, die ausschließlich dem König dienten."] },
      { number: 39, text: "Der Priester Zadok hatte das Horn mit dem Salböl aus dem heiligen Zelt geholt und salbte Salomo nun damit. Dann wurden die Widderhörner geblasen, und alles Volk rief: \"Es lebe König Salomo!\"" },
      { number: 40, text: "Nun zog das ganze Volk hinter ihm her in die Stadt hinauf. Sie spielten auf Flöten und waren außer sich vor Freude. Von ihrem Jubelgeschrei barst schier die Erde." },
      { number: 41, text: "Auch Adonija und seine Gäste hörten den Lärm, als sie gerade ihr Festmahl beendet hatten. Joab fragte, als er die Hörner hörte: \"Was ist das für ein Lärm in der Stadt?\"" },
      { number: 42, text: "Da kam auch schon Jonatan, der Sohn des Priesters Abjatar. Adonija sagte: \"Komm her, du bist ein zuverlässiger Mann und bringst sicher eine gute Nachricht!\"" },
      { number: 43, text: "\"Nein!\", erwiderte Jonatan. \"Unser Herr, König David, hat Salomo zum König gemacht." },
      { number: 44, text: "Er hat den Priester Zadok und den Propheten Natan, Benaja Ben-Jojada und die Leibgarde mit ihm geschickt, und sie haben ihn auf der Mauleselin des Königs reiten lassen." },
      { number: 45, text: "Zadok und Natan haben ihn an der Gihonquelle zum König gesalbt. Dann sind alle mit Freudengeschrei wieder hinaufgezogen. Die ganze Stadt ist in Bewegung. Das ist der Lärm, den ihr gehört habt." },
      { number: 46, text: "Und darüber hinaus hat Salomo auf dem Königsthron Platz genommen." },
      { number: 47, text: "Die Dienstleute des Königs sind auch schon hineingegangen, um König David, unserem Herrn, ihre Segenswünsche zu überbringen. Sie sagen: 'Dein Gott mache den Namen Salomos noch berühmter als deinen Namen und seine Herrschaft noch größer als deine!' Und der König hat sich auf seinem Lager vor Gott verneigt." },
      { number: 48, text: "Und außerdem hat der König gesagt: 'Gepriesen sei Jahwe, der Gott Israels, der es heute geschenkt hat, dass einer meiner Söhne auf meinem Thron sitzt und meine Augen es noch sehen dürfen.'\"" },
      { number: 49, text: "Da erschraken alle Gäste Adonijas. Sie standen auf und liefen auseinander; jeder ging seinen eigenen Weg." },
      { number: 50, text: "Adonija selbst bekam auch Angst vor Salomo. Er lief zum Brandopferaltar und ergriff dessen Hörner*.", footnotes: ["Die Hörner waren Vorsprünge an den vier Ecken des Altars, an die das Opferblut gestrichen wurde. Offenbar galten sie auch als Zufluchtsstellen."] },
      { number: 51, text: "Salomo wurde gemeldet: \"Sieh doch, Adonija hat Angst vor dem König Salomo. Er hat die Hörner des Altars umklammert und sagt: 'König Salomo soll mir heute schwören, dass er seinen Diener nicht mit dem Schwert töten lässt.'\"" },
      { number: 52, text: "Salomo sagte: \"Wenn er sich als redlicher Mann erweist, wird ihm kein Haar gekrümmt. Doch wenn er sich etwas zuschulden kommen lässt, muss er sterben.\"" },
      { number: 53, text: "Damit ließ ihn Salomo vom Altar herunterholen. Adonija kam zum König und warf sich vor ihm nieder. \"Geh nach Hause!\", sagte dieser zu ihm." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Als es nun mit Davids Leben zu Ende ging, gab er seinem Sohn Salomo folgende Weisungen:", heading: "Davids letzte Anweisungen" },
      { number: 2, text: "\"Ich gehe nun den Weg alles Irdischen. Sei stark und erweise dich als Mann!" },
      { number: 3, text: "Halte dich an das, was Jahwe, dein Gott, von dir fordert. Geh auf seinen Wegen und beachte seine Ordnungen und Gebote, seine Anweisungen und Zeugnisse, wie sie im Gesetz Moses aufgeschrieben sind. Dann wirst du in allem Erfolg haben, was du auch planst und unternimmst." },
      { number: 4, text: "Dann wird auch Jahwe sein Versprechen halten, das er mir gegeben hat. Er sagte: 'Wenn deine Söhne auf ihren Weg achten und wahrhaftig mit ganzem Herzen und ganzer Seele vor mir leben, dann wird es dir nie an einem Nachkommen auf dem Thron Israels fehlen.'" },
      { number: 5, text: "Noch etwas: Du weißt selbst, was mir Joab Ben-Zeruja angetan hat. Er hat die beiden Heerführer Israels Abner Ben-Ner und Amasa Ben-Jeter kaltblütig umgebracht. So hat er Kriegsblut auf den Frieden gegossen und sich selbst mit dem Blut an Gürtel und Schuhen besudelt." },
      { number: 6, text: "Sorge in deiner Weisheit dafür, dass sein graues Haar nicht in Frieden zu den Toten kommt!" },
      { number: 7, text: "Doch die Söhne des Barsillai aus Gilead* sollst du freundlich behandeln. Sie sollen mit zu denen gehören, die an deinem Tisch essen, denn sie haben auch mich versorgt, als ich vor deinem Bruder Abschalom fliehen musste.", footnotes: ["Gilead bezeichnet das mittlere, manchmal auch das ganze Ostjordanland."] },
      { number: 8, text: "Da ist auch noch Schimi Ben-Gera, der Benjaminit aus Bahurim*. Das ist der, der mich damals, als ich nach Mahanajim* ging, böse verflucht hat. Doch ist er mir dann an den Jordan entgegen gekommen, und ich habe ihm bei Jahwe geschworen, dass ich ihn nicht töten lasse.", footnotes: ["Bahurim war ein Ort östlich vom Ölberg.", "Mahanajim lag wahrscheinlich 11 km östlich vom Jordan am Jabbok."] },
      { number: 9, text: "Aber jetzt muss er seine Strafe bekommen. Du bist ein kluger Mann und weißt, was du mit ihm tun musst. Sorge dafür, dass sein graues Haar blutig zu den Toten kommt!\"" },
      { number: 10, text: "Bald darauf starb David und wurde in der Davidsstadt* beigesetzt.", footnotes: ["Die Davidsstadt umfasste das Gebiet des alten Jebus, das von David erobert worden war. Es bildete den Kern Jerusalems."] },
      { number: 11, text: "Vierzig Jahre lang war er König über Israel, sieben Jahre in Hebron und 33 in Jerusalem." },
      { number: 12, text: "Salomo saß nun auf dem Thron seines Vaters David und hatte die Herrschaft fest in der Hand." },
      { number: 13, text: "Eines Tages kam Adonija Ben-Haggit zu Salomos Mutter Batseba. \"Kommst du in Frieden?\", fragte sie ihn. \"Ja, Schalom*\", erwiderte er,", heading: "Salomos erste Maßnahmen", footnotes: ["Schalom war der Friedensgruß in Israel und bedeutete gleichzeitig: Es ist alles in Ordnung!"] },
      { number: 14, text: "\"ich habe nur eine Bitte an dich.\" – \"Sprich!\", erwiderte sie." },
      { number: 15, text: "Da sagte er: \"Du weißt, dass eigentlich mir das Königtum zustand. Ganz Israel erwartete, dass ich König würde. Aber nun kam es anders, und das Königtum ist meinem Bruder zugefallen. Jahwe hatte es eben für ihn bestimmt." },
      { number: 16, text: "Jetzt habe ich nur eine einzige Bitte; schlag sie mir nicht ab!\" – \"Sprich!\", erwiderte sie." },
      { number: 17, text: "Da begann er: \"Rede doch mit König Salomo, dich wird er nicht abweisen. Bitte ihn, mir Abischag aus Schunem zur Frau zu geben.\"" },
      { number: 18, text: "\"Gut\", sagte Batseba, \"ich will mit dem König reden.\"" },
      { number: 19, text: "Als Batseba zu König Salomo hineinging, um wegen Adonija mit ihm zu reden, stand der König auf und verneigte sich tief vor ihr. Dann setzte er sich wieder auf seinen Thron und ließ auch einen Thron für die Königsmutter aufstellen. So saß sie an seiner rechten Seite." },
      { number: 20, text: "\"Ich habe nur eine einzige kleine Bitte an dich\", sagte sie, \"schlag sie mir nicht ab!\" – \"Sprich nur, Mutter\", sagte der König, \"ich werde dir nichts abschlagen.\"" },
      { number: 21, text: "Sie sagte: \"Man könnte doch Abischag von Schunem deinem Bruder Adonija zur Frau geben.\"" },
      { number: 22, text: "Da erwiderte König Salomo seiner Mutter: \"Warum bittest du für Adonija nur um Abischag von Schunem? Fordere doch gleich das Königtum für ihn, er ist schließlich mein älterer Bruder!* Auch der Priester Abjatar und Joab Ben-Zeruja hätten sicher nichts dagegen.\"", footnotes: ["Fordere ... Bruder. Salomo hatte sofort verstanden, dass Adonijas Bitte ein indirekter Anspruch auf den Thron war, denn der Nachfolger des Königs übernahm gewöhnlich den Harem des Vorgängers, zu dem Abischag gehörte, obwohl sie noch unberührt war."] },
      { number: 23, text: "Dann schwor er bei Jahwe: \"Gott soll mich strafen, wenn Adonija dieses Ansinnen nicht mit seinem Leben büßt!" },
      { number: 24, text: "So wahr Jahwe lebt, der mich als König bestätigt und auf den Thron meines Vaters David gesetzt hat, der sein Wort gehalten und auch meinen Nachkommen das Königtum zugesagt hat: Noch heute muss Adonija sterben!\"" },
      { number: 25, text: "König Salomo beauftragte Benaja Ben-Jojada damit. Der stach ihn nieder. So starb Adonija." },
      { number: 26, text: "Zum Priester Abjatar sagte der König: \"Geh auf dein Landgut nach Anatot! Du hast zwar den Tod verdient, aber heute will ich dich nicht töten lassen, weil du die Bundeslade Jahwes, unseres Herrn, vor meinem Vater David getragen und alle Leiden mit ihm geteilt hast.\"" },
      { number: 27, text: "Damit entzog Salomo Abjatar das Recht, Jahwe als Priester zu dienen. So erfüllte sich das Wort Jahwes, das er der Familie des Priesters Eli in Schilo angekündigt hatte.*", footnotes: ["angekündigt hatte. Siehe 1. Samuel 2,30-35."] },
      { number: 28, text: "Als Joab davon hörte, floh er zum Zelt Jahwes und umklammerte die Hörner des Altars. Er hatte sich zwar nicht auf die Seite Abschaloms gestellt, wohl aber auf die Adonijas." },
      { number: 29, text: "König Salomo wurde gemeldet: \"Joab ist zum Zelt Jahwes an den Altar geflohen.\" Da schickte Salomo Benaja Ben-Jojada mit dem Befehl los, Joab zu töten." },
      { number: 30, text: "Benaja ging ins Zelt Jahwes* und sagte zu Joab: \"Der König befiehlt: Verlass diesen Ort!\" – \"Nein\", erwiderte dieser, \"dann will ich hier sterben!\" Benaja ging zum König zurück und berichtete ihm, was Joab gesagt hatte.", footnotes: ["Zelt Jahwes. Gemeint ist der umzäunte Vorhof, in dem auch der Brandopferaltar stand."] },
      { number: 31, text: "\"Tu, was er gesagt hat\", erwiderte der König. \"Stoß ihn nieder und begrabe ihn. So nimmst du die Blutschuld von mir und der Familie meines Vaters, die Joab auf uns gebracht hat." },
      { number: 32, text: "Jahwe wird diese Blutschuld auf ihn selbst zurückbringen. Denn er hat zwei Männer getötet, die gerechter und besser waren als er. Er hat Abner Ben-Ner, den Heerführer Israels, und Amasa Ben-Jeter, den Heerführer Judas, mit dem Schwert umgebracht, ohne dass mein Vater David davon wusste." },
      { number: 33, text: "Diese Blutschuld soll für immer auf Joab und seinen Nachkommen lasten. Aber auf David und seinen Nachkommen, seiner Familie und seinem Thron möge immer der Frieden Jahwes ruhen.\"" },
      { number: 34, text: "Da ging Benaja wieder hin und erstach Joab. Man begrub ihn auf seinem Grundstück in der Wüste." },
      { number: 35, text: "Der König setzte dann Benaja an Joabs Stelle über das Heer und den Priester Zadok an die Stelle Abjatars." },
      { number: 36, text: "Dann ließ der König Schimi rufen und sagte zu ihm: \"Bau dir ein Haus in Jerusalem und wohne dort! Du darfst die Stadt nicht mehr verlassen." },
      { number: 37, text: "Du sollst genau wissen: Sobald du den Bach Kidron* überquerst, musst du sterben! Dann wirst du selbst an deinem Tod Schuld sein.\"", footnotes: ["Der Bach Kidron floss im Osten Jerusalems dem Toten Meer zu und führte nur während der winter-lichen Regenzeit Wasser."] },
      { number: 38, text: "\"Ja, das ist gut\", erwiderte Schimi, \"dein Diener wird tun, was mein Herr, der König, gesagt hat.\" So wohnte Schimi lange in Jerusalem." },
      { number: 39, text: "Drei Jahre später jedoch entliefen ihm zwei seiner Sklaven. Sie flohen zu Achisch Ben-Maacha, dem König von Gat*. Als Schimi hörte, dass seine Sklaven in Gat waren,", footnotes: ["Gat war eine der fünf Philisterstädte und lag etwa 55 km südwestlich von Jerusalem."] },
      { number: 40, text: "sattelte er seinen Esel und ritt zu Achisch nach Gat, um seine Sklaven zu suchen. Er zog also hin und holte sie aus Gat zurück." },
      { number: 41, text: "Man berichtete Salomo, dass Schimi von Jerusalem nach Gat geritten und wieder zurückgekehrt sei." },
      { number: 42, text: "Da ließ der König Schimi zu sich rufen und sagte zu ihm: \"Habe ich dich nicht gewarnt und dir gesagt: 'Sobald du die Stadt verlässt, musst du sterben!' Und du hast geantwortet: 'Ja, das ist gut, ich gehorche!' Ich habe dich sogar bei Jahwe schwören lassen." },
      { number: 43, text: "Warum hast du diesen Eid gebrochen und meinen Befehl missachtet?\"" },
      { number: 44, text: "Dann fuhr der König fort: \"Du weißt außerdem ganz genau, was du meinem Vater David angetan hast. So wird Jahwe deine Bosheit jetzt auf dich selbst zurückbringen." },
      { number: 45, text: "Der König Salomo aber wird gesegnet sein, und Jahwe wird dafür sorgen, dass die Königsherrschaft für alle Zeiten Davids Nachkommen gehört.\"" },
      { number: 46, text: "Der König gab Benaja den Befehl, und dieser führte Schimi hinaus und erstach ihn. Nun war die Herrschaft fest in der Hand Salomos." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Salomo wurde Schwiegersohn des Pharao, des Königs von Ägypten. Er nahm dessen Tochter zur Frau und ließ sie in der Davidsstadt wohnen, bis er seinen Palast, den Bau des Hauses Jahwes und die Stadtmauer vollendet hatte.", heading: "Salomos Gebet um Weisheit" },
      { number: 2, text: "Das Volk opferte bis dahin auf den Opferhöhen, denn bis zu diesem Zeitpunkt war dem Namen Jahwes noch kein Haus gebaut worden." },
      { number: 3, text: "Salomo liebte Jahwe und richtete sich nach den Anordnungen seines Vaters David. Aber auch er musste diese Opferhöhen benutzen, um Schlacht- und Räucheropfer darzubringen." },
      { number: 4, text: "So ging er nach Gibeon*, um die Opfer zu bringen, denn dort war die größte Opferstätte. Tausend Brandopfer legte Salomo auf den Altar.", footnotes: ["Gibeon lag etwa 10 km nordwestlich von Jerusalem. Nach 1. Chronik 21,29 und 2. Chronik 1,2-6 standen dort das Zelt der Gottesbegegnung und der ursprüngliche Bronzealtar aus der Zeit Moses."] },
      { number: 5, text: "Dort in Gibeon erschien Jahwe Salomo in der Nacht im Traum. Gott sagte: \"Sprich aus, was ich dir geben soll!\"" },
      { number: 6, text: "Salomo erwiderte: \"Du hast deinem Diener David, meinem Vater, große Gnade erwiesen, weil er treu und gerecht war und aufrichtig vor dir gelebt hat. Du hast ihm diese große Gunst erhalten und ihm einen Sohn geschenkt, der heute auf seinem Thron sitzt." },
      { number: 7, text: "Und nun, Jahwe, mein Gott, du selbst hast deinen Diener anstelle meines Vaters zum König gemacht. Doch ich bin noch sehr jung und weiß weder aus noch ein." },
      { number: 8, text: "Dein Diener steht mitten in dem Volk, das du erwählt hast. Es ist ein großes Volk mit vielen Menschen, die niemand zählen kann." },
      { number: 9, text: "So gib deinem Diener ein Herz, das auf dich hört, damit er dein Volk recht richten und zwischen Gut und Böse unterscheiden kann. Wie kann ich sonst dieses schwierige Volk regieren?\"" },
      { number: 10, text: "Gott, der Herr, freute sich über diese Bitte Salomos." },
      { number: 11, text: "Deshalb sagte er zu ihm: \"Weil du gerade um diese Sache gebeten hast und nicht um ein langes Leben, Reichtum oder den Tod deiner Feinde, sondern um Verstand zum Hören auf das Recht," },
      { number: 12, text: "darum werde ich deinen Wunsch erfüllen. Pass auf! Ich gebe dir ein weises und verständiges Herz, sodass kein Mensch vor oder nach dir mit dir verglichen werden kann." },
      { number: 13, text: "Und auch das, was du nicht erbeten hast, gebe ich dir, nämlich Reichtum und Ehre, sodass zu deinen Lebzeiten keiner von den Königen dir gleich kommt." },
      { number: 14, text: "Und wenn du auf meinen Wegen gehst, dich nach meinen Ordnungen und Geboten richtest, wie es dein Vater David getan hat, schenke ich dir auch ein langes Leben.\"" },
      { number: 15, text: "Da erwachte Salomo und merkte, dass es ein Traum war. Er ging nach Jerusalem, trat vor die Bundeslade des Herrn und opferte Brandopfer. Er ließ auch Tiere für das Freudenopfer* schlachten und ein Festmahl für seine Diener zubereiten.", footnotes: ["Beim Freudenopfer wurde im Gegensatz zum Brandopfer nur das Fett auf dem Altar verbrannt. Der größte Teil des Tieres durfte bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden."] },
      { number: 16, text: "Eines Tages traten zwei Prostituierte vor den König.", heading: "Das salomonische Urteil" },
      { number: 17, text: "Die eine sagte: \"Bitte, mein Herr! Diese Frau wohnt mit mir zusammen in einem Haus. Sie war dabei, als mein Kind geboren wurde." },
      { number: 18, text: "Zwei Tage später* bekam auch sie ein Kind. Wir beide waren ganz allein im Haus, kein Fremder war bei uns.", footnotes: ["Zwei Tage später. Wörtlich: am dritten Tag. Nach hebräischer Zählweise bedeutet das nicht drei, sondern zwei Tage später, weil die angebrochenen Tage gewöhnlich als volle Tage gerechnet wurden."] },
      { number: 19, text: "Eines Nachts starb der Sohn dieser Frau, weil sie ihn im Schlaf erdrückt hatte." },
      { number: 20, text: "Da stand sie mitten in der Nacht auf, holte meinen Sohn von meiner Seite weg und legte ihn zu sich, während ich, deine Dienerin, schlief. Ihren toten Sohn aber legte sie neben mich." },
      { number: 21, text: "Als ich nun am Morgen erwachte und meinen Sohn stillen wollte, merkte ich auf einmal, dass er tot war. Doch als ich ihn genauer ansah, entdeckte ich, dass es gar nicht das Kind war, das ich geboren hatte.\"" },
      { number: 22, text: "\"Das ist nicht wahr!\", rief die andere Frau. \"Mein Sohn ist der lebende, und deiner der tote!\" – \"Nein\", rief die erste, \"dein Sohn ist der tote und meiner der lebendige!\" So stritten sie sich vor dem König." },
      { number: 23, text: "Da sagte der König: \"Die eine behauptet: 'Der hier, der lebende ist mein Sohn. Dein Sohn ist der tote!', die andere sagt: 'Nein, dein Sohn ist der tote und mein Sohn der lebende!'\"" },
      { number: 24, text: "Dann befahl er: \"Holt mir ein Schwert!\" Sie brachten es dem König." },
      { number: 25, text: "Er sagte: \"Teilt das lebendige Kind in zwei Teile und gebt die eine Hälfte der einen und die andere Hälfte der anderen.\"" },
      { number: 26, text: "Da rief die Frau, deren Sohn der lebende war – denn es wurde ihr heiß vor Angst um ihren Sohn: \"Bitte, mein Herr! Gebt ihr das lebende Kind, aber tötet es ja nicht!\" Die andere aber sagte: \"Es soll weder dir noch mir gehören, zerschneidet es nur!\"" },
      { number: 27, text: "Da befahl der König: \"Gebt der ersten das lebende Kindchen und tötet es ja nicht! Sie ist seine Mutter.\"" },
      { number: 28, text: "Ganz Israel hörte von dem Urteil, das der König gefällt hatte, und alle bekamen große Ehrfurcht vor ihm. Denn sie sahen, dass Gott ihm seine Weisheit geschenkt hatte, sodass er gerechte Urteile fällen konnte." },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Salomo war nun König über ganz Israel.", heading: "Die Verwaltung des Reiches" },
      { number: 2, text: "Als oberste Beamte hatte er folgende Männer eingesetzt: Asarja Ben-Zadok als Priester," },
      { number: 3, text: "Elihoref und Ahija, die Söhne von Schischa, als Staatsschreiber, Joschafat Ben-Ahilud als Kanzler," },
      { number: 4, text: "Benaja Ben-Jojada als Heerführer, Zadok und Abjatar als Priester," },
      { number: 5, text: "Asarja Ben-Natan als Vorsteher der Vögte, den Priester Sabud Ben-Natan als Freund des Königs," },
      { number: 6, text: "Ahischar als Palastverwalter und Adoniram Ben-Abda als Beauftragter für die Zwangsarbeit." },
      { number: 7, text: "Salomo hatte Israel in zwölf Bezirke eingeteilt, die von Vögten verwaltet wurden. Diese hatten reihum je einen Monat lang die Versorgung des königlichen Hofs zu übernehmen." },
      { number: 8, text: "Hier sind ihre Namen: Ben-Hur für das Bergland von Efraïm;" },
      { number: 9, text: "Ben-Deker für das Gebiet der Städte Makaz, Schaalbim, Bet-Schemesch, Ajalon und Bet-Hanan;" },
      { number: 10, text: "Ben-Hesed für die Stadt Arubbot, das Gebiet von Socho und das ganze Land Hefer;" },
      { number: 11, text: "Ben-Abinadab – seine Frau war Salomos Tochter Tafat – für das Hügelland von Dor;" },
      { number: 12, text: "Baana Ben-Ahilud für Taanach und Megiddo, das ganze Gebiet um Bet-Schean in der Nähe von Zaretan, unterhalb von Jesreel, von Bet-Schean bis Abel-Mehola gegenüber von Jokneam;" },
      { number: 13, text: "Ben-Geber für die Stadt Ramot in Gilead, für die Zeltdörfer Jaïr Ben-Manasses in Gilead und das Gebiet von Argob in Baschan mit 60 großen Städten, die Mauern mit Torriegeln aus Bronze hatten;" },
      { number: 14, text: "Ahinadab Ben-Iddo für das Gebiet um Mahanajim;" },
      { number: 15, text: "Ahimaaz – seine Frau war Salomos Tochter Basemat – für das Stammesgebiet von Naftali;" },
      { number: 16, text: "Baana Ben-Huschai für das Stammesgebiet von Ascher und das Gebiet um Bealot;" },
      { number: 17, text: "Joschafat Ben-Paruach für das Stammesgebiet von Issachar;" },
      { number: 18, text: "Schimi Ben-Ela für das Stammesgebiet von Benjamin;" },
      { number: 19, text: "Geber Ben-Uri für das Gebiet von Sihon, dem König der Amoriter, und Og, dem König von Baschan im Land Gilead. Für das Land Juda war nur ein Vogt zuständig." },
      { number: 20, text: "Das Volk von Juda und Israel war zahlreich wie der Sand am Meer. Es hatte zu essen und zu trinken und war glücklich." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Salomo herrschte über alle Königreiche vom Euphrat bis zum Gebiet der Philister und zur Grenze Ägyptens. Sie zahlten ihm Tribut und erkannten seine Oberherrschaft an, solange er lebte.", heading: "Salomos Tempelbau (5-8)\nSalomos Hofhaltung" },
      { number: 2, text: "Für seine Hofhaltung benötigte Salomo täglich drei Tonnen Feinmehl und sechs Tonnen* gewöhnliches Mehl,", footnotes: ["drei ... sechs Tonnen. Wörtlich: 30 und 60 Kor. 1 Kor = 10 Efa. 1 Efa Mehl = 10 bis 12 Kilogramm."] },
      { number: 3, text: "zehn gemästete Rinder, zwanzig Weiderinder und hundert Schafe. Dazu kamen noch Hirsche, Gazellen, Damhirsche und gemästete Vögel." },
      { number: 4, text: "Salomo herrschte über das ganze Gebiet diesseits des Euphrat von Tifsach* bis Gaza* und über alle Könige, die dort regierten. Mit allen Völkern ringsum hatte er Frieden.", footnotes: ["Tifsach lag am Westufer des Euphrat an der großen Biegung.", "Gaza war die bedeutendste Stadt der Philister, sechs Kilometer vom Mittelmeer entfernt."] },
      { number: 5, text: "Solange Salomo lebte, ging es Juda und Israel gut. Von Dan bis Beerscheba* konnte jeder ungestört unter seinem Weinstock und Feigenbaum sitzen.", footnotes: ["Dan bis Beerscheba. Das meint vom nördlichsten bis zum südlichsten Ort in Israel."] },
      { number: 6, text: "Salomo hatte 4000* Stallplätze für seine Streitwagengespanne und 12.000 Pferde.", footnotes: ["4000. So mit LXX und 2. Chronik 9,25. MT liest 40.000, was wohl durch ungenaues Abschreiben entstand."] },
      { number: 7, text: "Die Vögte versorgten den König und alle, die an seiner Tafel speisen durften. Jeder war für einen Monat verantwortlich. Sie ließen es an nichts fehlen." },
      { number: 8, text: "Sie schafften auch Gerste und Stroh für die Pferde und die Wagenpferde heran, jeweils an den Ort, für den jeder zuständig war." },
      { number: 9, text: "Gott schenkte Salomo Weisheit, sehr viel Verstand und ein umfassendes Wissen wie Sand am Ufer des Meeres.", heading: "Salomos Weisheit" },
      { number: 10, text: "Salomos Weisheit übertraf die Weisheit aller im Osten lebenden Menschen und auch die Weisheit Ägyptens." },
      { number: 11, text: "Er war weiser als alle Menschen und übertraf selbst Etan, den Esrachiter, und Heman, Kalkol und Darda, die Söhne Mahols. Sein Ruhm verbreitete sich bei allen Völkern ringsum." },
      { number: 12, text: "Er verfasste 3000 Weisheitssprüche und 1005 Lieder." },
      { number: 13, text: "Er beschrieb die Bäume von der Zeder auf dem Libanon bis zum Ysop, der an der Mauer wächst, das Vieh, die Vögel, das Gewürm und die Fische." },
      { number: 14, text: "Aus allen Völkern kamen Menschen, um die Weisheit Salomos zu vernehmen, und alle Könige der Erde, die von seiner Weisheit gehört hatten, schickten Gesandte zu ihm." },
      { number: 15, text: "König Hiram von Tyrus* war immer ein Freund Davids gewesen. Als er hörte, dass man Salomo als Nachfolger seines Vaters zum König gesalbt hatte, schickte er eine Gesandtschaft zu ihm.", heading: "Vorbereitungen für den Tempelbau", footnotes: ["Tyrus war die wichtigste Hafenstadt an der phönizischen Küste, 56 km nördlich vom Berg Karmel."] },
      { number: 16, text: "Und Salomo ließ Hiram ausrichten:" },
      { number: 17, text: "\"Du weißt ja, dass mein Vater David wegen der Kriege, die ihm seine Feinde ringsherum aufzwangen, für Jahwe, seinen Gott, kein Haus bauen konnte. Doch schließlich hatte Jahwe ihm seine Feinde unter die Füße gelegt." },
      { number: 18, text: "Und mir hat Jahwe, mein Gott, ringsherum Ruhe verschafft. Es gibt keinen Gegner und kein böses Hindernis mehr." },
      { number: 19, text: "Darum habe ich mich entschlossen, für den Namen meines Gottes, für Jahwe, ein Haus zu bauen. Denn so hatte es Jahwe meinem Vater David gesagt: 'Dein Sohn, den ich als deinen Nachfolger auf den Thron setzen werde, soll meinem Namen ein Haus bauen.'" },
      { number: 20, text: "So lass nun auf dem Libanon Zedern für mich schlagen. Meine Arbeiter werden deinen Leuten zur Hand gehen. Natürlich erstatte ich dir den Lohn für deine Leute, du musst nur sagen, wie viel. Du weißt ja, dass wir hier keinen haben, der Bauholz so zu schlagen versteht wie die Sidonier.\"" },
      { number: 21, text: "Als Hiram die Botschaft Salomos vernahm, freute er sich sehr und sagte: \"Heute sei Jahwe gelobt, der David einen weisen Sohn für dieses große Volk geschenkt hat.\"" },
      { number: 22, text: "Und an Salomo schickte Hiram folgende Antwort: \"Es ist gut angekommen, was du mir übermittelt hast. Ich bin gern bereit, dir deinen Wunsch nach Zedern- und Zypressenholz zu erfüllen." },
      { number: 23, text: "Meine Leute sollen die Stämme vom Libanon zum Meer hinunterschaffen. Dann lasse ich sie zu Flößen zusammenbinden und sie an der Küste entlang an den Ort bringen, den du mir angibst. Dort lasse ich die Flöße wieder auseinandernehmen und du kannst das Holz abholen lassen. Dafür sollst du meinen Wunsch erfüllen und mir Lebensmittel für meinen Hof liefern.\"" },
      { number: 24, text: "Hiram lieferte Salomo also das Zedern- und Zypressenholz, das er brauchte." },
      { number: 25, text: "Dafür lieferte Salomo Hiram jährlich 3.200 Tonnen* Weizen und 440.000 Liter* reines Olivenöl.", footnotes: ["3200 Tonnen. Wörtlich: 20.000 Kor. 1 Kor = 10 Efa. 1 Efa Getreidekörner = 16 bis 17 Kilogramm.", "440.000 Liter. Wörtlich: 20 Kor. Bei 1 Kor = 220 Liter ergeben sich 4.400 Liter. Mit 2. Chronik 2,9liest die LXX 20.000 Bat. Bei 1 Bat = 22 Liter ergeben sich 440.000 Liter, was heute 18 Tanklaster füllen würde."] },
      { number: 26, text: "Jahwe hatte Salomo Weisheit geschenkt, wie er es ihm versprochen hatte. Es herrschte Frieden zwischen Hiram und Salomo, und die beiden schlossen ein Bündnis." },
      { number: 27, text: "König Salomo ließ in ganz Israel 30.000 Zwangsarbeiter einziehen" },
      { number: 28, text: "und stellte sie unter die Leitung Adonirams. Jeweils 10.000 mussten einen Monat auf dem Libanon arbeiten und waren dann zwei Monate zu Hause." },
      { number: 29, text: "Darüber hinaus hatte Salomo 70.000 Lastträger und 80.000 Steinhauer im Gebirge." },
      { number: 30, text: "Dazu kamen 3300 Aufseher, die den Vögten unterstellt waren und die Arbeiten überwachten." },
      { number: 31, text: "Der König ordnete an, große quaderförmige Steinblöcke von bester Qualität für die Grundmauern des Hauses zu brechen." },
      { number: 32, text: "Die Bauleute von Salomo und Hiram bearbeiteten zusammen mit den Männern von Byblos* die Steinblöcke und Stämme.", footnotes: ["Männer von Byblos. Wörtlich: Gebaliter. Das waren Bewohner der Stadt Gebal = Byblos nördlich von Beirut."] },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Im 480. Jahr nach dem Auszug der Israeliten aus Ägypten*, es war das vierte Jahr*, in dem Salomo über Israel regierte, im Mai, dem Blumenmonat*, begann der König das Haus für Jahwe zu bauen.", heading: "Der Tempelbau", footnotes: ["Der Auszug aus Ägypten muss nach biblischer Chronologie (siehe Vorwort des Übersetzers) also 1446 v.Chr. stattgefunden haben. Das entspricht auch Jiftachs Aussage in Richter 11,26.", "vierten Jahres ... regierte. Das vierte Jahr Salomos war das Jahr 967 v.Chr.", "Blumenmonat. Althebräisch: Siw = 2. Monat."] },
      { number: 2, text: "Dieses Haus, das Salomo für Jahwe baute, war 30 Meter lang, 10 Meter breit und 15 Meter hoch.*", footnotes: ["30 Meter Wörtlich: 60 Ellen."] },
      { number: 3, text: "Die Halle vor dem Haus war zehn Meter breit und fünf Meter tief." },
      { number: 4, text: "Im Haus waren auch Fensteröffnungen mit Rahmen und Gitterwerk." },
      { number: 5, text: "Außen an den Seitenwänden und der Hinterwand ließ er einen mehrstöckigen Anbau errichten." },
      { number: 6, text: "Der untere Anbau war zweieinhalb Meter breit, der mittlere drei Meter und der obere dreieinhalb Meter, weil sich die Mauer des Tempelhauses in diesen Stufen nach oben verjüngte. So mussten die Balken nicht in die Tempelmauer eingelassen werden, sondern konnten aufliegen." },
      { number: 7, text: "Beim Bau des Hauses wurden Steine verwendet, die man schon im Steinbruch fertig behauen hatte. So waren weder Hämmer noch Meißel oder sonstige eiserne Werkzeuge auf der Baustelle zu hören." },
      { number: 8, text: "Der Eingang zum Anbau war auf der rechten Seite des Hauses. Über Wendeltreppen gelangte man zum mittleren und oberen Stockwerk." },
      { number: 9, text: "Als die Mauern fertig waren, ließ Salomo das Haus mit Balken und Bohlen aus Zedernholz decken." },
      { number: 10, text: "Der Anbau fasste das Haus ganz mit Zedernbalken ein. Jedes Stockwerk war zweieinhalb Meter hoch." },
      { number: 11, text: "Damals kam folgendes Wort Jahwes zu Salomo:" },
      { number: 12, text: "\"Du baust mir dieses Haus. Wenn du nach meinen Ordnungen lebst, meine Vorschriften befolgst und meine Gebote hältst und darin lebst, dann werde ich auch zu meinem Wort stehen, das ich deinem Vater David gegeben habe." },
      { number: 13, text: "Ich werde mitten unter den Israeliten wohnen und mein Volk Israel nicht verlassen.\"" },
      { number: 14, text: "Nachdem Salomo den Rohbau vollendet hatte,", heading: "Der Innenausbau" },
      { number: 15, text: "ließ er die Wände des Hauses mit Zedernholz täfeln, und zwar vom Fußboden bis zu den Deckbalken. Den Fußboden selbst ließ er mit Zypressenholz auslegen." },
      { number: 16, text: "Zehn Meter vor der Rückwand des Hauses ließ er eine Zwischenwand aus Zedernholz errichten, um hinten einen Raum für das Höchstheilige zu schaffen." },
      { number: 17, text: "Der Tempelraum davor war noch 20 Meter lang." },
      { number: 18, text: "Er war ganz mit Zedernholz getäfelt, so dass keine Mauer mehr zu sehen war. Die Täfelung war mit Schnitzereien von wilden Kürbissen und Blütenkelchen versehen." },
      { number: 19, text: "Den hinteren Raum im Haus ließ Salomo herrichten, weil er dort die Bundeslade Jahwes aufstellen wollte." },
      { number: 20, text: "Dieser Raum war zehn Meter lang, zehn Meter breit und zehn Meter hoch. Er ließ ihn mit reinem Gold überziehen. Auch den Zedernholzaltar überzog er damit," },
      { number: 21, text: "ebenso die Wände des Tempelhauses. Vor dem hinteren Raum ließ Salomo goldene Ketten anbringen." },
      { number: 22, text: "So überzog er das ganze Haus vollständig mit Gold, auch den Altar, der zum hinteren Raum gehörte." },
      { number: 23, text: "Im hinteren Raum ließ er zwei fünf Meter hohe Cherubim* aus Olivenholz anfertigen.", footnotes: ["Cherub (Mehrzahl: Cherubim). Majestätisches (Engel-)Wesen, das Gottes Herrlichkeit repräsentiert."] },
      { number: 24, text: "Ihre Flügel maßen je zweieinhalb Meter, so dass sie ausgespannt fünf Meter breit waren." },
      { number: 25, text: "So war es auch bei dem anderen Cherub. Beide Cherubim hatten genau die gleiche Größe und Gestalt." },
      { number: 26, text: "Beide waren fünf Meter hoch." },
      { number: 27, text: "Er ließ die Cherubim mitten in diesem innersten Teil des Hauses aufstellen, sodass ihre ausgespannten Flügel sich in der Mitte berührten und außen bis an die Seitenwände reichten." },
      { number: 28, text: "Auch die Cherubim wurden mit Gold überzogen." },
      { number: 29, text: "Alle Wände des Hauses im inneren und im äußeren Raum wurden mit eingeschnitzten Reliefs von Cherubim, Palmen und Blumengebinden geschmückt." },
      { number: 30, text: "Die Fußböden wurden mit Gold überzogen." },
      { number: 31, text: "Der Eingang zum hinteren Raum bekam Türflügel aus Olivenholz, die von einem fünffach gestaffelten Türrahmen eingefasst waren." },
      { number: 32, text: "Auf die beiden Türflügel waren Cherubim, Palmen und Blumengebinde eingeschnitzt. Sie wurden dann ganz mit Gold überzogen. In die Cherubim- und Palmenornamente wurde das Gold aufgehämmert." },
      { number: 33, text: "Ebenso war es mit dem Eingang zum Tempelraum. Die vierfach gestaffelten Türrahmen waren aus Olivenholz." },
      { number: 34, text: "Die beiden Türflügel, von denen jeder zwei drehbare Blätter besaß, bestanden aber aus Zypressenholz." },
      { number: 35, text: "Sie waren mit eingeschnitzten Cherubim, Palmen und Blumengebinden verziert, deren Vertiefungen mit Gold ausgeschlagen wurden." },
      { number: 36, text: "Den inneren Vorhof ließ Salomo mit einer Mauer von drei Lagen Quadern und einer Lage Zedernholzbalken umgeben." },
      { number: 37, text: "Im Blumenmonat* seines vierten Regierungsjahrs war die Grundmauer für das Haus Jahwes gelegt worden,", footnotes: ["siehe Vers 1."] },
      { number: 38, text: "und im November seines elften Jahrs, dem Regenmonat*, war es mit seiner gesamten Einrichtung vollendet. Sieben Jahre hatte Salomo daran gebaut.", footnotes: ["Regenmonat. Althebräisch Bul = 8. Monat."] },
    ] },
    { number: 7, verses: [
      { number: 1, text: "An seiner eigenen Palastanlage baute Salomo 13 Jahre, bis alles fertig war.", heading: "Die königlichen Paläste" },
      { number: 2, text: "Er baute das Libanonwaldhaus, das 50 Meter lang, 25 Meter breit und 15 Meter hoch war. Seine Tragbalken waren aus Zedernholz und ruhten auf vier Reihen von Zedernsäulen." },
      { number: 3, text: "Im Obergeschoss befanden sich 45 Räume, die mit Zedernbrettern gedeckt waren, je 15 in einer Reihe." },
      { number: 4, text: "Die Saalfenster waren in drei Reihen angebracht, die sich genau gegenüberstanden." },
      { number: 5, text: "Die Rahmen aller Türen waren vierfach abgestuft. Auch an dieser Seite standen je dreimal ein Fenster dem anderen gegenüber." },
      { number: 6, text: "Er baute auch die Säulenvorhalle, 25 Meter lang und 15 Meter breit. Sie hatte noch einen Vorbau mit Säulen und davor einen Aufgang." },
      { number: 7, text: "Er baute die Vorhalle zum Thronsaal, in der er Gericht hielt. Deshalb hieß sie auch Gerichtshalle. Sie war vom Boden bis zur Decke mit Zedernholz getäfelt." },
      { number: 8, text: "Das Haus, in dem Salomo selbst wohnte, lag hinter der Vorhalle im anderen Hof. Es war von derselben Bauart, ebenso auch das Haus für die Tochter des Pharao, die er geheiratet hatte." },
      { number: 9, text: "Alle diese Gebäude waren vom Grund bis zum Gesims aus besten Quadersteinen errichtet, die außen und innen mit der Steinsäge geschnitten waren." },
      { number: 10, text: "Die Fundamente bestanden aus wertvollen, mächtigen Steinblöcken, einige fünf und andere vier Meter lang." },
      { number: 11, text: "Darauf wurden Mauern aus Quadersteinen errichtet, auf denen Zedernbalken lagen." },
      { number: 12, text: "Der große Hof war wie der Vorhof und die Vorhalle vom Haus Jahwes von einer Mauer umgeben, die aus drei Lagen Quadersteinen und einer Lage Zedernbalken bestand." },
      { number: 13, text: "König Salomo ließ Hiram aus Tyrus kommen.", heading: "Die Ausstattung des Tempels" },
      { number: 14, text: "Er war der Sohn einer Witwe aus dem Stamm Naftali. Sein Vater war Tyrer, ein Bronzeschmied. Hiram war sehr begabt, ein Meister seines Fachs, und konnte alle möglichen Gegenstände aus Bronze herstellen. Er kam zu König Salomo und führte alle Arbeiten für ihn aus." },
      { number: 15, text: "Er formte die beiden Bronzesäulen, jede neun Meter hoch. Ihr Umfang betrug sechs Meter." },
      { number: 16, text: "Oben auf jede Säule setzte er ein in Bronze gegossenes Kapitell von zweieinhalb Metern Höhe." },
      { number: 17, text: "Für die Kapitelle wurden kettenartige Bänder angefertigt und je sieben davon an jedem angebracht." },
      { number: 18, text: "Dann machte er die Granatäpfel und befestigte sie in zwei Reihen auf dem Geflecht, das die Kapitelle oben bedeckte." },
      { number: 19, text: "Die Kapitelle sahen wie zwei Meter hohe Blütenkelche aus," },
      { number: 20, text: "die die Säulen über der Ausbuchtung krönten. Dazu kamen die 200 Granatäpfel in Reihen ringsherum." },
      { number: 21, text: "Dann wurden die Säulen vor der Eingangshalle des Tempels aufgestellt. Die rechte wurde Jachin, \"Er richtet auf\", genannt und die linke Boas, \"In ihm ist Stärke\"." },
      { number: 22, text: "Als dann die lilienförmigen Gebilde auf den Säulenköpfen ruhten, war die Arbeit an den Säulen vollendet." },
      { number: 23, text: "Dann machte Hiram das so genannte Meer, ein gegossenes Becken mit einem Durchmesser von fünf Metern. Seine Höhe betrug zweieinhalb Meter, und eine Schnur von 15 Metern Länge umspannte es." },
      { number: 24, text: "Unterhalb des Randes war es mit zwei Reihen von Buckeln verziert, von denen zehn auf einen halben Meter kamen. Diese Buckelverzierungen waren aus einem Guss mit dem Becken." },
      { number: 25, text: "Das Becken selbst stand auf zwölf Rindern, deren Hinterteile nach innen gekehrt waren. Jeweils drei von ihnen schauten nach Norden, Westen, Süden und Osten." },
      { number: 26, text: "Der Rand des Beckens war wie bei einem Kelch oder einer Lilienblüte nach außen gewölbt und etwa eine Handbreit dick. Das Becken fasste 44.000 Liter*.", footnotes: ["44.000 Liter. Hebräisch: 2000 Bat. 1 Bat ~ 22 Liter."] },
      { number: 27, text: "Hiram machte auch zehn Gestelle aus Bronze, jedes zwei Meter lang, zwei Meter breit und anderthalb Meter hoch." },
      { number: 28, text: "Und so waren die Gestelle gebaut: Sie bestanden aus Leisten. Zwischen den Eckleisten waren Verschlussplatten angebracht." },
      { number: 29, text: "Darauf befanden sich Abbilder von Löwen, Rindern und Cherubim. Oben und unten waren sie von gehämmerten Kränzen eingefasst." },
      { number: 30, text: "Jedes Gestell hatte zwei Achsen und vier Räder aus Bronze. Die vier Füße waren durch Seitenstücke mit der unteren verzierten Leiste vergossen." },
      { number: 31, text: "Der Aufsatz, der den Kessel innerhalb der Umkrönung aufnahm, ragte noch 50 Zentimeter darüber hinaus. Er war in einen viereckigen Untersatz von 75 Zentimetern Seitenlänge eingesetzt und mit Schnitzwerk verziert.*", footnotes: ["Der hebräische Text in diesem Vers ist nicht sicher zu deuten."] },
      { number: 32, text: "Die vier Räder befanden sich unterhalb der Leisten, und die Radzapfen waren am Gestell befestigt. Die Räder selbst hatten einen Durchmesser von 75 Zentimetern." },
      { number: 33, text: "Sie waren wie Wagenräder gebaut. Achsen, Felgen, Speichen und Naben waren gegossen." },
      { number: 34, text: "Die vier Eckpfosten und der Wagenkasten waren aus einem Guss." },
      { number: 35, text: "Der ringförmige Aufsatz auf dem Gestell ragte 25 Zentimeter darüber hinaus und war durch Halter mit dem Gestell fest verbunden." },
      { number: 36, text: "Auf den Seitenplatten und den Haltern waren Cherubim, Löwen und Palmen eingraviert, und ringsherum waren Kränze angebracht." },
      { number: 37, text: "Auf diese Weise machte Hiram alle zehn Gestelle aus derselben Gussform nach demselben Plan und Maß." },
      { number: 38, text: "Dann machte er für jedes Gestell einen Kessel aus Bronze. Jeder Kessel fasste 880 Liter und hatte einen Durchmesser von zwei Metern." },
      { number: 39, text: "Fünf der Kesselwagen erhielten ihren Platz auf der rechten Seite und fünf auf der linken Seite des Hauses. Das sogenannte Meer wurde an der Südostecke aufgestellt." },
      { number: 40, text: "Hiram fertigte auch die Töpfe, Schaufeln und Sprengschalen und vollendete alle Arbeiten, die König Salomo ihm für das Haus Jahwes aufgetragen hatte:" },
      { number: 41, text: "zwei Säulen und die wulstförmigen Kapitelle, die auf den Säulen ruhten; dazu die Geflechte, um die beiden Kapitelle zu bedecken;" },
      { number: 42, text: "die 400 Granatäpfel, die in zwei Reihen an den Geflechten hingen;" },
      { number: 43, text: "die zehn Gestelle mit den Kesseln darauf;" },
      { number: 44, text: "das so genannte Meer und die zwölf Rinder darunter" },
      { number: 45, text: "und die Töpfe, Schaufeln und Sprengschalen. Alle diese Gegenstände waren aus blanker Bronze." },
      { number: 46, text: "In der Jordanebene hatte der König sie gießen lassen und zwar in den Tonablagerungen zwischen Sukkot und Zaretan*.", footnotes: ["Sukkot und Zaretan liegen etwa 34 km nordöstlich von Jericho auf der Ostseite des Jordan und der Nordseite des Jabbok."] },
      { number: 47, text: "Allen Gegenständen gab Salomo ihren Platz. Wegen ihrer übergroßen Menge war das Gewicht der verarbeiteten Bronze nicht festzustellen." },
      { number: 48, text: "Salomo ließ auch die Gegenstände anfertigen, die zum Haus Jahwes gehören: den goldenen Altar und den goldenen Tisch für die geweihten Brote," },
      { number: 49, text: "die Leuchter aus reinem Gold, von denen fünf rechts und fünf links vor dem hinteren Raum standen. Dazu die blütenförmigen Aufsätze für die Lichtschalen und die Dochtscheren, alles aus Gold." },
      { number: 50, text: "Dann die Becken, Messer, Schalen, Schüsseln und Feuerpfannen aus reinem Gold, die Angeln für die Türflügel des Tempelraums und des Höchstheiligen, ebenfalls aus Gold." },
      { number: 51, text: "So wurden alle Arbeiten, die König Salomo für das Haus Jahwes ausführen ließ, vollendet. Dann brachte Salomo die heiligen Gaben seines Vaters David hinein. Das Silber und das Gold und alle Gegenstände kamen in die Schatzkammern des Hauses Jahwes." },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Dann ließ Salomo die Ältesten von Israel, die Oberhäupter der Stämme und die Fürsten der Sippen Israels nach Jerusalem kommen. Sie sollten die Bundeslade Jahwes aus der Davidsstadt Zion in den Tempel hinaufbringen.", heading: "Die Überführung der Bundeslade" },
      { number: 2, text: "Zum Laubhüttenfest, das im Oktober, dem Herbstmonat*, stattfindet, versammelten sich alle Männer Israels beim König.", footnotes: ["Herbstmonat. Althebräisch Etanim = 7. Monat. Salomo hatte mit der Einweihung offenbar fast ein Jahr gewartet, siehe Kapitel 6,38."] },
      { number: 3, text: "In Gegenwart der Ältesten Israels nahmen die Priester die Lade" },
      { number: 4, text: "und trugen sie zum Tempel hinauf. Auch das Zelt der Gottesbegegnung und die heiligen Gegenstände, die im Zelt waren, wurden von den Priestern und Leviten hinaufgebracht." },
      { number: 5, text: "König Salomo und die ganze Gemeinschaft Israels, die sich bei ihm vor der Lade eingefunden hatte, opferten eine unzählbare Menge von Schafen und Rindern." },
      { number: 6, text: "Dann brachten die Priester die Bundeslade Jahwes an ihren Platz im hintersten Raum des Hauses, dem Höchstheiligen, unter die Flügel der Cherubim." },
      { number: 7, text: "Die Cherubim hielten ihre Flügel nämlich über dem Platz der Lade ausgebreitet und überspannten damit die Lade und ihre Tragestangen." },
      { number: 8, text: "Die Stangen waren so lang, dass man ihre Enden vom Heiligtum aus nur sehen konnte, wenn man direkt vor dem hinteren Raum stand. Sonst waren sie vom Heiligtum aus nicht zu sehen. Die Lade befindet sich noch heute* dort.", footnotes: ["heute. Das meint den Zeitpunkt, als die Königsbücher verfasst wurden."] },
      { number: 9, text: "In ihr waren nur die beiden Tafeln, die Mose am Horeb hineingelegt hatte, als Jahwe den Bund mit den Israeliten bei deren Auszug aus Ägypten schloss*.", footnotes: ["Tafeln ... schloss. Vergleiche 2. Mose 25,21; 32,19-20; 34,1-4.28-29."] },
      { number: 10, text: "Als die Priester aus dem Heiligtum auszogen, erfüllte die Wolke das ganze Haus Jahwes." },
      { number: 11, text: "Die Priester konnten ihren Dienst nicht fortsetzen, denn die Herrlichkeit Jahwes erfüllte das Haus Jahwes." },
      { number: 12, text: "Da betete Salomo: \"Jahwe hat gesagt, dass er im Wolkendunkel wohnen will." },
      { number: 13, text: "Ich habe dir nun ein Herrscherhaus gebaut, eine Stätte, wo du für immer wohnen sollst.\"" },
      { number: 14, text: "Dann drehte sich der König um und segnete die ganze Versammlung Israels. Alle standen.", heading: "Die Ansprache Salomos" },
      { number: 15, text: "Dann sagte er: \"Gepriesen sei Jahwe, der Gott Israels, der wahr machte, was er meinem Vater David versprach:" },
      { number: 16, text: "'Seit der Zeit, als ich mein Volk aus Ägypten führte, habe ich in keinem der Stämme Israels eine Stadt erwählt, um dort einen Wohnsitz für meinen Namen errichten zu lassen. Aber David habe ich bestimmt, Herrscher über mein Volk zu sein.'" },
      { number: 17, text: "Nun war es meinem Vater David ein Anliegen, dem Namen Jahwes, des Gottes Israels, ein Haus zu bauen." },
      { number: 18, text: "Doch Jahwe sagte zu meinem Vater David: 'Wenn du dir vorgenommen hast, meinem Namen ein Haus zu bauen, hast du einen guten Entschluss gefasst." },
      { number: 19, text: "Aber nicht du, sondern dein leiblicher Sohn soll dieses Haus meinem Namen bauen.'" },
      { number: 20, text: "Und Jahwe hat dieses Versprechen gehalten. Ich bin an die Stelle meines Vaters David getreten und habe den Thron Israels bestiegen, wie Jahwe es zugesagt hat. Und ich habe nun das Haus für den Namen Jahwes, des Gottes Israels, gebaut" },
      { number: 21, text: "und einen Platz für die Lade hergerichtet, in der die Tafeln des Bundes liegen, den Jahwe mit den Israeliten schloss, nachdem er sie aus Ägypten herausgeführt hatte.\"" },
      { number: 22, text: "Dann trat Salomo vor den Augen der Versammlung Israels zum Altar Jahwes. Er breitete seine Hände zum Himmel aus", heading: "Salomos Gebet zur Tempelweihe" },
      { number: 23, text: "und sagte:\"Jahwe, Gott Israels! Kein Gott ist dir vergleichbar, weder im Himmel noch auf der Erde. Du stehst zu deinem Bund und erhältst deinen Dienern deine Güte, denen, die vor dir leben und dir mit ganzem Herzen dienen." },
      { number: 24, text: "Du hast auch deinem Diener, meinem Vater David, deine Versprechen gehalten. Was du mit dem Mund versprachst, hast du mit der Hand erfüllt, wie es dieser Tag zeigt." },
      { number: 25, text: "Jahwe, Gott Israels, nun erfülle auch die andere Zusage, die du meinem Vater David gegeben hast, als du sagtest: 'Es soll dir nie an einem Mann fehlen, der vor mir auf dem Thron Israels sitzt, wenn nur deine Söhne darauf achten, so nach meinen Weisungen zu leben, wie du das getan hast.'" },
      { number: 26, text: "Du Gott Israels, lass doch in Erfüllung gehen, was du deinem Diener David, meinem Vater, zugesagt hast!" },
      { number: 27, text: "Aber will Gott wirklich auf der Erde wohnen? Selbst der Himmel und das ganze Universum können dich nicht fassen, geschweige denn dieses Haus, das ich gebaut habe!" },
      { number: 28, text: "Trotzdem bitte ich dich, Jahwe, mein Gott, achte doch auf das Gebet deines Dieners und sein Flehen, hör auf sein Rufen und seine Bitten, die er heute vor dich bringt." },
      { number: 29, text: "Halte deine Augen Tag und Nacht über diesem Haus offen, von dem du gesagt hast, dass dein Name dort wohnen soll, und höre auf das Gebet, das dein Diener zu dieser Stätte hin richtet!" },
      { number: 30, text: "Höre doch auf das Flehen, das dein Diener und dein Volk zu dieser Stätte hin richten werden! Höre du es selbst in deiner himmlischen Wohnung, dort, wo du thronst! Ja, erhöre uns und vergib!" },
      { number: 31, text: "Wenn jemand sich an seinem Nächsten versündigt und dieser einen Eid* von ihm verlangt und er kommt vor deinen Altar in dieses Haus und spricht diesen Eid aus,", footnotes: ["Eid ... verlangt. Siehe 2. Mose 22,10-12; 4. Mose 5,11-31."] },
      { number: 32, text: "dann höre es vom Himmel her und greife ein! Verschaff deinen Dienern Recht! Bestrafe den Schuldigen und lass sein böses Tun auf ihn selbst zurückfallen, den Schuldlosen aber sprich frei und gib ihm, was seiner Gerechtigkeit entspricht." },
      { number: 33, text: "Und wenn dein Volk Israel von Feinden besiegt wird, weil es gegen dich gesündigt hat, und dann wieder umkehrt und deinen Namen preist und in diesem Haus zu dir betet und fleht," },
      { number: 34, text: "dann höre du es im Himmel und vergib deinem Volk Israel seine Schuld und bring es wieder in das Land zurück, das du ihren Vorfahren gegeben hast." },
      { number: 35, text: "Wenn sich der Himmel verschließt, dass es nicht regnet, weil sie gegen dich gesündigt haben, und sie dann zu dieser Stätte hin beten und deinen Namen preisen und von ihrer Sünde umkehren, weil du sie gedemütigt hast," },
      { number: 36, text: "dann höre du es im Himmel und vergib deinen Dienern und deinem Volk Israel die Sünde – denn du führst sie den rechten Weg – und lass es wieder regnen auf dein Land, das du deinem Volk als Grundbesitz gegeben hast." },
      { number: 37, text: "Wenn eine Hungersnot im Land ausbricht, wenn die Pest wütet, wenn das Getreide durch Brand- oder Rostpilze, Heuschrecken oder andere Schädlinge vernichtet wird, wenn der Feind ins Land einfällt, wenn irgendeine Krankheit oder Plage sie trifft," },
      { number: 38, text: "dann höre du jedes Gebet und Flehen. Sei es ein Einzelner oder dein ganzes Volk, je nachdem, was einer als seine Plage oder seinen Schmerz erkennt, wenn er seine Hände nach diesem Haus hin ausbreitet," },
      { number: 39, text: "dann höre du es im Himmel, dem Ort, wo du thronst! Und vergib; und gib jedem, was er verdient! Denn du kennst die verborgenen Gedanken der Menschen und siehst ihnen ins Herz." },
      { number: 40, text: "Dann werden sie dich fürchten und auf deinen Wegen gehen, solange sie in dem Land leben, das du unseren Vätern gegeben hast." },
      { number: 41, text: "Auch wenn ein Ausländer, der nicht zu deinem Volk Israel zählt, deinetwegen aus einem fernen Land kommt," },
      { number: 42, text: "– denn sie werden von deinem großen Namen hören und von dem, was du mit deiner starken Hand und deinem ausgestreckten Arm getan hast – wenn er also kommt und zu diesem Haus hin betet," },
      { number: 43, text: "dann höre du es im Himmel, dem Ort, wo du thronst, und erfülle seine Bitte! So werden alle Völker der Erde deinen Namen erkennen und dich fürchten, wie dein Volk Israel es tut. Und sie werden wissen, dass dein Name über diesem Haus, das ich gebaut habe, ausgerufen ist." },
      { number: 44, text: "Wenn dein Volk gegen seine Feinde in den Krieg zieht, egal wohin du sie schickst, und sie dann zu dir beten in Richtung dieser Stadt, die du erwählt hast, und dieses Hauses, das ich deinem Namen gebaut habe," },
      { number: 45, text: "dann höre ihr Gebet und Flehen im Himmel und verschaffe ihnen ihr Recht!" },
      { number: 46, text: "Wenn sie gegen dich sündigen – denn es gibt keinen Menschen, der nicht sündigt – und du über sie zornig wirst und sie ihren Feinden auslieferst, und diese sie in ein fernes oder nahes Land verschleppen," },
      { number: 47, text: "und sie es sich dort zu Herzen nehmen und kehren um und flehen im Land ihrer Gefangenschaft zu dir und sagen: 'Wir haben gesündigt, wir haben Unrecht getan, wir haben gottlos gehandelt!';" },
      { number: 48, text: "wenn sie in dem Land, in dem sie gefangen sind, anhaltend und mit ganzem Herzen und ihrer ganzen Seele zu dir umkehren und beten in Richtung dieses Landes, das du ihren Vätern gegeben hast, und dieser Stadt, die du erwählt hast, und dieses Hauses, das ich deinem Namen gebaut habe," },
      { number: 49, text: "dann höre ihr Gebet und Flehen im Himmel, dem Ort, wo du thronst, und schaffe ihnen ihr Recht!" },
      { number: 50, text: "Und vergib deinem Volk, was es gegen dich gesündigt hat und womit es sich an dir verging, und lass sie bei ihren Bezwingern Erbarmen finden!" },
      { number: 51, text: "Sie sind doch dein Volk und dein Eigentum, das du aus Ägypten, diesem glühenden Schmelzofen, herausgeführt hast!" },
      { number: 52, text: "Lass deine Augen über dem Flehen deines Dieners und deines Volkes Israel offen sein, dass du auf sie hörst, sooft sie zu dir rufen!" },
      { number: 53, text: "Denn du hast dir Israel aus allen Völkern der Welt zum Eigentum erwählt, wie du es schon durch deinen Diener Mose gesagt hast, als du unsere Vorfahren aus Ägypten herausführtest, Herr, Jahwe!\"" },
      { number: 54, text: "Als Salomo dieses Gebet und sein Flehen zu Jahwe beendet hatte, stand er wieder auf. Er hatte sich nämlich beim Beten vor dem Altar Jahwes hingekniet und seine Hände zum Himmel ausgebreitet.", heading: "Salomos Segen" },
      { number: 55, text: "Nun trat er vor die Versammlung Israels und segnete sie. Er rief laut:" },
      { number: 56, text: "\"Gepriesen sei Jahwe, der seinem Volk Israel Ruhe verschafft hat, wie er es versprochen hatte. All die guten Worte, die er uns durch seinen Diener Mose zugesagt hat, sind eingetroffen; kein einziges davon ist ausgeblieben." },
      { number: 57, text: "Möge Jahwe, unser Gott, mit uns sein, wie er auch mit unseren Vätern war. Er möge uns nie verlassen, uns niemals verstoßen!" },
      { number: 58, text: "Er lasse unsere Herzen auf ihn gerichtet sein, damit wir auf seinen Wegen gehen und die Gebote, Vorschriften und Rechte einhalten, die er unseren Vorfahren gegeben hat." },
      { number: 59, text: "Mögen diese Worte, mit denen ich vor Jahwe um Gnade gefleht habe, ihm, unserem Gott, Tag und Nacht gegenwärtig sein, damit er seinem Diener und seinem Volk Recht verschaffe, wie jeder Tag es verlangt." },
      { number: 60, text: "Dann werden alle Völker der Welt erkennen, dass Jahwe der alleinige Gott ist." },
      { number: 61, text: "Und ihr sollt mit ungeteiltem Herzen bei Jahwe, unserem Gott, bleiben, nach seinen Vorschriften leben und seine Gebote halten, wie ihr es heute tut.\"" },
      { number: 62, text: "Dann feierten der König und das ganze Volk ein Opfermahl vor Jahwe.", heading: "Abschluss der Feier" },
      { number: 63, text: "Salomo ließ zu diesem Anlass 22.000 Rinder und 120.000 Schafe schlachten. So weihten sie das Haus Jahwes ein." },
      { number: 64, text: "Zu diesem besonderen Anlass weihte Salomo den mittleren Teil des Vorhofs vor dem Haus Jahwes zum Opferaltar. Denn dort ließ er die Brandopfer und die Fettstücke der Freudenopfer verbrennen, weil der Bronzealtar, den er hatte anfertigen lassen, für die Menge der Brand- und Speisopfer und Fettstücke zu klein war." },
      { number: 65, text: "Salomo feierte damals auch noch das Laubhüttenfest mit ganz Israel sieben Tage lang. Es war eine sehr große Versammlung aus dem ganzen Land zusammengekommen, von Lebo-Hamat* bis zum Bach Ägyptens*. Sie feierten insgesamt 14 Tage lang.", footnotes: ["Lebo-Hamat. Heute: Labwe, etwa 70 km nördlich vom Berg Hermon.", "Bach Ägyptens. Nach Josua 15,4war das die Grenze zwischen Israel und Ägypten. Heute: Wadi El-Arisch."] },
      { number: 66, text: "Am Tag nach dem Laubhüttenfest verabschiedete Salomo das Volk. Alle dankten dem König und freuten sich über das Gute, das Jahwe seinem Diener David und seinem Volk Israel geschenkt hatte, und zogen voller Zuversicht nach Hause." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Als nun Salomo das Haus Jahwes und das Haus für den König vollendet hatte und alles gut gelungen war, was er sich vorgenommen hatte,", heading: "Salomos Wohlstand und Abstieg (9-11)\nGottes Antwort" },
      { number: 2, text: "erschien ihm Jahwe ein zweites Mal, so wie er ihm in Gibeon erschienen war." },
      { number: 3, text: "Jahwe sagte zu ihm:\"Ich habe dein Gebet und dein Flehen zu mir erhört und habe dieses Haus, das du gebaut hast, für mich ausgesondert. Ich werde meinen Namen für immer mit diesem Haus verbinden. Meine Augen und mein Herz werden immer dort sein." },
      { number: 4, text: "Und du, wenn du so vor mir lebst wie dein Vater David, aufrichtig mit Herz und Hand, wenn du also meine Gebote, Vorschriften und Rechte beachtest," },
      { number: 5, text: "dann werde ich deine Herrschaft über Israel bestehen lassen, wie ich es deinem Vater David zugesagt habe, als ich den Bund mit ihm schloss: 'Es soll dir nie an einem Mann auf dem Thron Israels fehlen.'" },
      { number: 6, text: "Wenn ihr euch aber von mir abwendet, wenn ihr meine Vorschriften und Gebote nicht mehr beachtet und stattdessen anderen Göttern nachlauft und euch vor ihnen niederwerft," },
      { number: 7, text: "dann werde ich Israel aus dem Land, das ich ihnen gegeben habe, herausreißen. Dann werde ich dieses Haus, das ich meinem Namen geheiligt habe, keines Blickes mehr würdigen. Dann wird Israel zum Gespött und zum Hohn für alle Völker." },
      { number: 8, text: "Und dieses Haus wird ein Trümmerhaufen sein. Jeder, der vorübergeht, wird sich dann entsetzt fragen: 'Warum hat Jahwe das diesem Land und diesem Haus angetan?'" },
      { number: 9, text: "Dann wird man ihnen antworten: 'Weil sie Jahwe, ihren Gott, der ihre Väter aus Ägypten herausführte, verlassen und sich anderen Göttern zugewandt haben. Weil sie ihnen gedient und sich vor ihnen niedergeworfen haben, hat er all dieses Unheil über sie gebracht.'\"" },
      { number: 10, text: "Zwanzig Jahre lang hatte Salomo am Haus Jahwes und an seinem Regierungspalast gebaut.", heading: "Salomos Unternehmungen" },
      { number: 11, text: "König Hiram von Tyrus hatte ihm nach seinem Wunsch Zedern- und Zypressenholz und Gold geliefert. Damals trat König Salomo Hiram zwanzig Städte in Galiläa ab." },
      { number: 12, text: "Hiram kam von Tyrus, um sie sich anzusehen, aber sie gefielen ihm nicht." },
      { number: 13, text: "\"Was sind das für Städte, die du mir da gegeben hast, mein Bruder\", sagte er zu Salomo. Er nannte sie Land Kabul, Ramsch-Land. So heißt die Gegend bis heute." },
      { number: 14, text: "Hiram hatte Salomo immerhin vier Tonnen Gold geliefert.*", footnotes: ["Was ... geliefert. Hiram wollte seine Lebensmittelversorgung auch nach Fertigstellung der Bauten für Salomo sichern. Deshalb war er mit dem Landstrich nicht zufrieden. Offenbar gab Salomo Hiram noch einiges kultiviertes Land in der Küstenebene dazu und erhielt im Gegenzug ein Gebiet im Hochland, das der Stamm Ascher eigentlich erobert haben sollte, und besiedelte es (2. Chronik 8,2)."] },
      { number: 15, text: "Salomo setzte bei allen Bauarbeiten Zwangsarbeiter ein: beim Bau des Hauses Jahwes und bei seinem eigenen Palast, beim Ausbau der Verteidigungsanlagen und der Stadtmauern von Jerusalem, Hazor*, Megiddo* und Geser*.", footnotes: ["Hazor. Wichtigste Festung im Norden, 14 km nördlich vom See von Galiläa.", "Megiddo. Bedeutende Stadt am Südwestrand des Jesreel-Tales. Die Festung bewachte einen wichtigen Pass, der durch die Karmel-Bergkette verlief.", "Geser. Stadt im nördlichen Teil der Schefela, 27 km südöstlich von Joppe."] },
      { number: 16, text: "Die Kanaaniterstadt Geser war vom Pharao, dem König von Ägypten, erobert und eingeäschert worden. Er hatte alle Einwohner töten lassen und dann die Stadt seiner Tochter als Mitgift in die Ehe mit Salomo gegeben." },
      { number: 17, text: "Salomo ließ Geser wieder aufbauen, dazu das untere Bet-Horon*", footnotes: ["Bet-Horon. Die Zwillingsstädte waren nur 3 km voneinander entfernt und beherrschten die wichtige Zugangsstraße von der Küstenebene ins Hügelland. Sie lagen 19 km nordwestlich von Jerusalem."] },
      { number: 18, text: "und Baalat* und Tamar* im Wüstenland,", footnotes: ["Baalat ist der ältere Name für Kirjat-Jearim an der Grenze von Juda und Benjamin. Heute: Deir el-Azar,14 km westlich von Jerusalem.", "Tamar. Wahrscheinlich ist nach 2. Chronik 8,4Tadmor gemeint, eine große Oase in der nordsyrischen Wüste. Heute: Palmyra, 208 km nordöstlich von Damaskus."] },
      { number: 19, text: "außerdem alle seine Vorratsstädte und die Städte, in denen er seine Streitwagentruppen stationiert hatte. Auch alles, was Salomo sonst noch in Jerusalem, auf dem Libanon und in seinem ganzen Herrschaftsgebiet bauen wollte, ließ er von Zwangsarbeitern errichten." },
      { number: 20, text: "Das waren Amoriter, Hetiter, Perisiter, Hewiter und Jebusiter, also keine Israeliten." },
      { number: 21, text: "Es waren Nachkommen der Bewohner des Landes, an denen die Israeliten nicht den Bann* vollstrecken konnten. Die machte Salomo zu Sklaven und zog sie zur Zwangsarbeit* heran. So ist es bis heute.", footnotes: ["Bann. Das bedeutete normalerweise die vollständige Vernichtung von Menschen, Tieren und Gütern.", "Zwangsarbeit. Israeliten wurden nur zeitweise dazu herangezogen (1. Könige 5,27-28), die genannten Sklaven dauerhaft."] },
      { number: 22, text: "Von den Israeliten machte Salomo keine Sklaven, sondern sie waren seine Soldaten, seine Beamten, seine Truppenführer und Streitwagenkämpfer." },
      { number: 23, text: "Im Dienst seiner Vögte standen 550 Beamte, die für die Bauarbeiten Salomos verantwortlich waren und die Zwangsarbeiter beaufsichtigten." },
      { number: 24, text: "Als die Tochter des Pharao aus der Davidsstadt in den Palast gezogen war, den Salomo für sie gebaut hatte, begann er mit den Arbeiten am Stadtwall." },
      { number: 25, text: "Dreimal im Jahr opferte Salomo Brand- und Freudenopfer auf dem Altar, den er für Jahwe gebaut hatte. Auch Räucheropfer verbrannte er auf diesem Altar vor Jahwe. So erfüllte das Haus seinen Zweck." },
      { number: 26, text: "In Ezjon-Geber bei Elat*, das an der Küste des Schilfmeeres in Edom* liegt, ließ Salomo eine Flotte bauen.", footnotes: ["Ezjon-Geber und Elat lagen am Nordende des Golfs von Akaba in der Nähe der Stadt Akaba.", "Edom. Land östlich der Araba und südlich vom Toten Meer, bewohnt von den Nachkommen Esaus."] },
      { number: 27, text: "Hiram stellte erfahrene Seeleute zur Verfügung, die mit den Männern Salomos fuhren." },
      { number: 28, text: "So segelten sie bis nach Ofir* und brachten von dort 16 Tonnen* Gold zum König Salomo.", footnotes: ["Ofir. Josephus, LXX und Vulgata (Hiob 28,16) verstanden darunter Indien. Dafür spricht, dass es alle in der Bibel erwähnten Güter (Gold, Silber, Edelsteine, Hölzer, Elfenbein, Affen und Pfauen) im alten Indien gab. Ferner ist bekannt, dass vom 2. Jahrtausend v. Chr. an ein lebhafter Handel zwischen dem Persischen Golf und Indien getrieben wurde. Dazu waren Hochseeschiffe (1. Könige 22,48: Tarschisch-Schiffe) nötig. Eine andere Theorie besagt, dass Ofir eine Stadt war, die vermutlich an der südwestlichen Küste Arabiens oder 75 km nördlich von Bombay (Supura) lag.", "16 Tonnen. Wörtlich: 450 Talente. Als Gewichtseinheit entspricht 1 Talent etwa 34,5 Kilogramm."] },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Als der Ruf Salomos und der Name Jahwes bis zur Königin von Saba* drang, kam sie, um Salomo mit schwierigen Fragen zu prüfen.", heading: "Die Königin von Saba zu Besuch", footnotes: ["Saba. Land im Süden Israels (siehe Matthäus 12,42), vielleicht auf der südwestlichen arabischen Halbinsel in der Nähe des heutigen Jemen. Die genaue Lage ist ungewiss."] },
      { number: 2, text: "Sie reiste mit einem gewaltigen Gefolge nach Jerusalem. Ihre Kamele waren schwer mit duftenden Ölen, Gold und Edelsteinen beladen. Als sie zu Salomo kam, besprach sie alles mit ihm, was sie sich überlegt hatte." },
      { number: 3, text: "Salomo beantwortete alle ihre Fragen. Es gab nichts, was ihm verborgen war und worauf er keine Antwort gewusst hätte." },
      { number: 4, text: "Als die Königin von Saba die Weisheit Salomos erkannte, als sie den Palast sah, den er gebaut hatte," },
      { number: 5, text: "die Speisen an seiner Tafel, die Sitzplätze seiner Beamten, die gute Bedienung und die kostbaren Gewänder seiner Diener und Mundschenke und das Brandopfer, das er im Haus Jahwes opfern ließ, verschlug es ihr den Atem." },
      { number: 6, text: "Sie sagte zum König: \"Es ist tatsächlich alles wahr, was ich in meinem Land über dich und deine Weisheit gehört habe!" },
      { number: 7, text: "Ich wollte es nicht glauben, bis ich es mit eigenen Augen gesehen hatte. Und nun sehe ich: Man hat mir nicht einmal die Hälfte gesagt. Deine Weisheit und dein Reichtum übertrifft alles, was ich je über dich gehört habe." },
      { number: 8, text: "Was für ein Vorrecht haben deine Männer, deine Minister, die täglich bei dir sind und deine weisen Worte hören." },
      { number: 9, text: "Gepriesen sei Jahwe, dein Gott, dem es gefiel, dich auf den Thron Israels zu setzen. Weil Jahwe Israel ewig liebt, hat er dich zum König gemacht, damit du für Recht und Gerechtigkeit sorgst.\"" },
      { number: 10, text: "Dann übergab sie dem König mehr als vier Tonnen* Gold, eine Menge duftender Öle und Edelsteine. Nie wieder hat es so viel kostbares Öl gegeben wie dieses, das die Königin von Saba Salomo als Geschenk überbrachte.", footnotes: ["vier Tonnen. Wörtlich: 120 Talente."] },
      { number: 11, text: "Die Flotte Hirams, die Gold aus Ofir holte, hatte eine große Menge Almuggimholz* und Edelsteine mitgebracht.", footnotes: ["Almuggim bezeichnet eine nicht näher bestimmbare sehr wertvolle Holzart."] },
      { number: 12, text: "Der König hatte aus dem Almuggimholz Geländer für das Haus Jahwes und den Regierungspalast anfertigen lassen und Zithern und Harfen für die Tempelsänger. Bis heute ist nie mehr so viel Almuggimholz nach Juda gekommen und hier gesehen worden." },
      { number: 13, text: "König Salomo erfüllte der Königin von Saba jeden Wunsch, den sie äußerte, und beschenkte sie darüber hinaus so reich, wie er nur konnte. Danach kehrte sie mit ihrem Gefolge wieder in ihr Land zurück." },
      { number: 14, text: "In einem einzigen Jahr gingen bei Salomo 23 Tonnen* Gold ein.", heading: "Salomos Reichtum", footnotes: ["23 Tonnen. Wörtlich: 666 Talente."] },
      { number: 15, text: "Dazu kam noch das, was die Händler einbrachten und was von allen Königen Arabiens und den Statthaltern des Landes einging." },
      { number: 16, text: "König Salomo ließ 200 Langschilde anfertigen und mit Gold überziehen. Sieben Kilogramm* gehämmertes Gold verwendete er für jeden Schild.", footnotes: ["sieben Kilogramm. Wörtlich: 600 (Schekel). Der königliche Schekel wog etwa 13 Gramm, der Schekel nach gefundenen Gewichten 11,5 Gramm."] },
      { number: 17, text: "Dazu ließ er noch 300 Kleinschilde machen und jeden mit dreieinhalb Kilogramm gehämmertem Gold überziehen. Er brachte sie alle in das Libanonwaldhaus*.", footnotes: ["Das Libanonwaldhaus war eine große Halle, die Salomo neben seinem Regierungspalast hatte bauen lassen, siehe Kapitel 7,2."] },
      { number: 18, text: "Weiter ließ der König einen großen Thron aus Elfenbein anfertigen und mit purem Gold überziehen." },
      { number: 19, text: "Der Thron hatte sechs Stufen und ein rundes Kopfstück hinten. Zu beiden Seiten des Sitzes befanden sich Armlehnen, neben denen zwei Löwenfiguren standen." },
      { number: 20, text: "Auch auf jeder der sechs Stufen stand rechts und links je eine Löwenfigur. Noch nie ist so etwas für ein Königreich geschaffen worden." },
      { number: 21, text: "Alle Trinkgefäße Salomos waren aus reinem Gold und auch sämtliche Gegenstände, die zum Libanonwaldhaus gehörten. Silber war zur Zeit Salomos wertlos," },
      { number: 22, text: "denn der König hatte hochseetüchtige Schiffe, die mit den Schiffen Hirams fuhren. Alle drei Jahre kam die Tarschisch-Flotte* und brachte Gold und Silber, Elfenbein, Affen und Pfauen.", footnotes: ["Tarschisch war die phönizische Kolonie Tartessus in Südspanien, wo Silber abgebaut wurde. Doch konnte offenbar auch ein anderes Gebiet im südlichen Teil des Roten Meeres, wo kostbare Metalle abgebaut wurden, so genannt werden (siehe 2. Chronik 20,36). Die großen hochseetüchtigen Handelsschiffe der Phönizier nannte man generell Tarschisch-Schiffe."] },
      { number: 23, text: "Somit übertraf König Salomo alle anderen Könige der Erde an Reichtum und Weisheit." },
      { number: 24, text: "Menschen aus aller Welt suchten ihn auf, um sich persönlich von der Weisheit zu überzeugen, die Gott ihm verliehen hatte." },
      { number: 25, text: "Alle brachten ihm Geschenke: silberne und goldene Gegenstände, Festgewänder und Waffen, kostbare Öle, Pferde und Maultiere. So ging es Jahr um Jahr." },
      { number: 26, text: "Salomo beschaffte sich 1400 Streitwagen und 12.000 Pferde. Er stationierte sie in den Wagenstädten und bei sich in Jerusalem." },
      { number: 27, text: "Unter seiner Regierung war Silber in Jerusalem so viel wert wie Steine, und Zedern so viel wie die Maulbeerfeigenbäume, die in der Niederung wachsen." },
      { number: 28, text: "Die Pferde bekam Salomo aus Ägypten und aus allen möglichen anderen Ländern. Seine Händler kauften sie dort auf." },
      { number: 29, text: "Bei der Ausfuhr aus Ägypten wurde ein Streitwagen mit 600 Silberstücken* gehandelt und ein Pferd mit 150. Seine Händler belieferten auch die Könige der Hetiter und Syrer.", footnotes: ["600 Sspanlberstücke. Wörtlich: Schekel. Das entspricht etwa 6,9 kg Silber für einen Streitwagen und 1,7 kg Silber (150 Schekel) für ein Pferd."] },
    ] },
    { number: 11, verses: [
      { number: 1, text: "König Salomo liebte aber viele ausländische Frauen, denn er hatte neben der Tochter des Pharao Frauen von den Moabitern*, den Ammonitern*, den Edomitern*, den Sidoniern* und den Hetitern* genommen.", heading: "Salomos Frauen und sein Götzendienst", footnotes: ["Die Moabiter lebten östlich des Toten Meeres zwischen den Flüssen Arnon und Zered.", "Die Ammoniter waren nordöstliche Nachbarn der Moabiter.", "Das Land Edom lag östlich der Araba im Süden des Toten Meeres und wurde von den Nachkommen Esaus, den Edomitern, bewohnt.", "Sidon, heute Saida im Libanon, war eine bedeutende Stadt Phöniziens, 40 km nördlich von Tyrus. Ihre Einwohner und die des ganzen Gebiets werden Sidonier genannt.", "Die aus Kleinasien stammenden Hetiter lebten damals in verschiedenen Stadtstaaten im Norden Syriens."] },
      { number: 2, text: "Jahwe hatte den Israeliten verboten, sich mit diesen Völkern zu vermischen. \"Sonst würden sie euch dazu verführen, auch ihre Götter zu verehren\", hatte er gesagt. Doch Salomo hing mit Liebe an diesen Frauen." },
      { number: 3, text: "Insgesamt hatte er 700 vornehme Frauen und 300 Nebenfrauen, die ihn immer mehr beeinflussten." },
      { number: 4, text: "Als er älter wurde, brachten sie ihn dazu, andere Götter zu verehren. Da war sein Herz nicht mehr ungeteilt Jahwe, seinem Gott, ergeben wie das Herz seines Vaters David." },
      { number: 5, text: "So verehrte Salomo Astarte*, die Göttin der Sidonier, und Milkom*, das Scheusal der Ammoniter.", footnotes: ["Die Astarte wurde als Fruchtbarkeits- und Liebesgöttin verehrt. Ihr Kult war möglicherweise mit sexuellen Riten verbunden.", "Milkom ist ein anderer Name für Moloch, dem auch Kinder geopfert wurden."] },
      { number: 6, text: "Auf diese Weise tat Salomo, was Jahwe missfiel. Er folgte ihm nicht so treu wie sein Vater David." },
      { number: 7, text: "Damals baute er auf einem Hügel östlich von Jerusalem ein Höhenheiligtum für Kemosch, das Scheusal der Moabiter, und für Moloch, das Scheusal der Ammoniter." },
      { number: 8, text: "Ebenso machte er es für alle seine ausländischen Frauen, damit sie ihren Göttern Räucheropfer bringen und Opfermahle feiern konnten." },
      { number: 9, text: "Da wurde Jahwe zornig über Salomo, weil dieser sich innerlich von ihm, dem Gott Israels, abgewandt hatte. Zweimal war er ihm erschienen", heading: "Jahwes Zorn über Salomo" },
      { number: 10, text: "und hatte ihm verboten, anderen Göttern zu folgen. Doch Salomo hatte nicht auf Jahwe gehört." },
      { number: 11, text: "Da sagte Jahwe zu ihm: \"Weil dir das alles bewusst war und du trotzdem meinen Bund und meine Weisungen nicht beachtet hast, werde ich dir das Königtum wegnehmen und es einem deiner Diener geben." },
      { number: 12, text: "Nur deinem Vater David zuliebe mache ich das nicht schon zu deinen Lebzeiten. Ich werde es tun, wenn dein Sohn die Herrschaft übernehmen will." },
      { number: 13, text: "Doch ich werde ihm nicht die ganze Herrschaft wegnehmen. Einen der zwölf Stämme werde ich ihm lassen, meinem Diener David und meiner erwählten Stadt Jerusalem zuliebe.\"" },
      { number: 14, text: "Jahwe ließ Salomo einen erbitterten Feind* erstehen. Er hieß Hadad und stammte aus der königlichen Familie von Edom.", footnotes: ["Feind. Hebräisch: Satan. Der Inbegriff für den Todfeind schlechthin."] },
      { number: 15, text: "Das kam so: David war im Krieg mit Edom, weil diese einige Israeliten erschlagen hatten.* Als nun sein Heerführer Joab in Edom einmarschierte, um die Erschlagenen zu begraben, brachte er außerdem alle männlichen Edomiter um.", footnotes: ["erschlagen hatten. Der mutmaßliche Kriegsgrund wurde zum besseren Verständnis eingefügt. Die Begebenheit wird sonst im Alten Testament nicht berichtet."] },
      { number: 16, text: "Sechs Monate blieb er mit dem ganzen Heer dort, bis alles getan war." },
      { number: 17, text: "Hadad war damals im jugendlichen Alter und konnte mit einigen edomitischen Männern, Gefolgsleuten seines Vaters, nach Ägypten entkommen." },
      { number: 18, text: "Sie waren über das Land Midian in die Oase Paran gelangt. Dort fanden sie ortskundige Männer, die sie zum Pharao nach Ägypten führten. Der ägyptische König gab ihm ein Haus und ein Stück Land und sorgte für seinen Unterhalt." },
      { number: 19, text: "Hadad gefiel ihm so gut, dass er ihm sogar die Schwester seiner Frau, also die Schwester der Königin Tachpenes, zur Frau gab." },
      { number: 20, text: "Diese schenkte ihm einen Sohn namens Genubat. Die Entwöhnung von der Mutterbrust feierte Tachpenes im Palast des Pharao. Von da an wuchs Genubat gemeinsam mit den Königssöhnen beim Pharao auf." },
      { number: 21, text: "Als nun Hadad in Ägypten hörte, dass David beigesetzt worden war und dass auch dessen Heerführer Joab tot war, sagte er zum Pharao: \"Lass mich bitte in mein Land zurückkehren!\"" },
      { number: 22, text: "\"Was fehlt dir denn bei mir?\", fragte der Pharao. \"Warum willst du in dein Land zurück?\" – \"Nicht doch\", sagte Hadad, \"entlass mich bitte!\"" },
      { number: 23, text: "Gott ließ Salomo noch einen anderen unerbittlichen Feind erstehen, Reson Ben-Eljada. Er hatte im Dienst Hadad-Esers, des Königs von Zoba*, gestanden und war geflohen,", footnotes: ["Zoba war ein kleines Königreich nördlich von Damaskus, das David besiegt hatte (2. Samuel 8,3-12; 10,6-19)."] },
      { number: 24, text: "als David die syrischen Hilfstruppen niedermachte. Er sammelte Männer um sich und wurde Führer einer Schar von Rebellen. Sie zogen nach Damaskus, nahmen die Stadt in Besitz und herrschten dort wie Könige." },
      { number: 25, text: "Solange Salomo lebte, war er sein erbitterter Feind und verabscheute Israel. Er vermehrte das Unheil, das von Hadad ausging, und wurde schließlich sogar König über Syrien." },
      { number: 26, text: "Auch Jerobeam Ben-Nebat, ein Beamter Salomos, erhob sich gegen den König. Er stammte aus Zereda in Efraïm. Seine Mutter war Witwe und hieß Zerua." },
      { number: 27, text: "Seine Rebellion gegen den König hatte folgende Ursache: Salomo hatte den Stadtwall bauen lassen, um die Lücke in der Stadt seines Vaters David zu schließen." },
      { number: 28, text: "Jerobeam war ein tüchtiger Mann. Als Salomo sah, wie der junge Mann arbeitete, übertrug er ihm die Aufsicht über alle Zwangsarbeiter des Hauses Josef*.", footnotes: ["Haus Josef meint die Stämme Efraïm und Manasse, die aus den Söhnen Josefs hervorgegangen waren."] },
      { number: 29, text: "Als Jerobeam einmal Jerusalem verließ, begegnete er dem Propheten Ahija von Schilo, der einen neuen Mantel trug. Als beide allein auf dem freien Feld waren," },
      { number: 30, text: "nahm Ahija seinen neuen Mantel und zerriss ihn in zwölf Stücke." },
      { number: 31, text: "Dann sagte er zu Jerobeam: \"Nimm dir zehn Stücke, denn so spricht Jahwe, der Gott Israels: 'Pass auf! Ich will Salomo die Herrschaft entreißen und dir zehn Stämme geben." },
      { number: 32, text: "Nur einen Stamm* lasse ich ihm, meinem Diener David zuliebe und meiner aus allen Stämmen Israels erwählten Stadt Jerusalem.", footnotes: ["einen Stamm. Das meint Juda und den mit ihm verbundenen kleinen Stamm Benjamin, siehe Kapitel 12,21."] },
      { number: 33, text: "So bestrafe ich die Israeliten dafür, dass sie mir den Rücken kehrten und sich niedergebeugt haben vor Astarte, der Göttin der Sidonier, vor Kemosch, dem Gott der Moabiter, und vor Milkom, dem Gott der Ammoniter. Sie sind nicht auf meinen Wegen geblieben und lebten nicht so, wie es mir gefällt. Salomo hat meine Vorschriften und Rechte nicht so beachtet wie sein Vater David." },
      { number: 34, text: "Und meinem Diener David zuliebe, den ich erwählt habe und der sich an meine Gebote und Vorschriften gehalten hat, werde ich Salomo das Königreich nicht nehmen, sondern ihn, solange er lebt, Fürst meines Volkes sein lassen." },
      { number: 35, text: "Aber seinem Sohn werde ich das Königtum wegnehmen und dir die Herrschaft über die zehn Stämme geben." },
      { number: 36, text: "Ihm lasse ich einen Stamm, damit mein Diener David stets einen Nachkommen vor mir in Jerusalem hat, der Stadt, die ich erwählt habe, dass mein Name dort wohnt." },
      { number: 37, text: "Dich aber mache ich zum König über alles, was du nur wünschen kannst. Du sollst König über Israel werden." },
      { number: 38, text: "Und wenn du auf das hörst, was ich dir gebiete, wenn du auf meinen Wegen gehst und tust, was mir gefällt, wenn du meine Vorschriften und Gebote beachtest wie mein Diener David, dann werde ich mit dir sein. Dann wird auch deine Nachkommenschaft bestehen bleiben, so wie ich es David für seine Nachkommen garantiert habe. Und dir gebe ich Israel." },
      { number: 39, text: "So werde ich Davids Nachkommenschaft demütigen, aber nicht für immer.'\"" },
      { number: 40, text: "Salomo wollte Jerobeam umbringen lassen, doch dieser entkam und floh nach Ägypten zu Schischak, dem ägyptischen König. Dort blieb er bis zu Salomos Tod." },
      { number: 41, text: "Was sonst noch über Salomo zu sagen ist, über seine Taten und seine Weisheit, findet man in der Chronik Salomos*.", footnotes: ["Chronik Salomos.Das war eine schriftliche Quelle über das Leben und die Regierung Salomos, die dem Verfasser der Königsbücher zur Verfügung stand."] },
      { number: 42, text: "Vierzig Jahre lang regierte Salomo über ganz Israel in Jerusalem." },
      { number: 43, text: "Als er gestorben war, bestattete man ihn in der Davidsstadt, und sein Sohn Rehabeam trat die Herrschaft an." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Rehabeam reiste nach Sichem*, denn ganz Israel war dorthin gekommen, um ihn als König zu bestätigen.", heading: "12-22: Geteiltes Reich und falscher Glaube\nDie Spaltung führt zum Götzendienst (12-16)\nDie Reichsteilung", footnotes: ["Sichem war eine strategisch und religiös bedeutende Stadt auf dem Pass (Sichem = Schulter) zwischen den Bergen Ebal im Norden und Garizim im Süden."] },
      { number: 2, text: "Als Jerobeam Ben-Nebat davon gehört hatte, war er aus Ägypten zurückgekehrt, wohin er vor Salomo hatte fliehen müssen." },
      { number: 3, text: "Nun ließen die Stämme Israels ihn rufen. Da stellte er sich zusammen mit ihnen vor Rehabeam und sagte:" },
      { number: 4, text: "\"Dein Vater hat uns ein hartes Joch auferlegt. Erleichtere uns jetzt die Last, die dein Vater uns aufgebürdet hat, und seine harte Zwangsarbeit, dann wollen wir dir untertan sein.\"" },
      { number: 5, text: "\"Kommt in drei Tagen wieder zu mir!\", erwiderte Rehabeam. Als das Volk gegangen war," },
      { number: 6, text: "beriet sich König Rehabeam mit den Alten, die bereits im Dienst seines Vaters Salomo gestanden hatten. Er fragte sie: \"Was ratet ihr mir? Welche Antwort soll ich dem Volk geben?\"" },
      { number: 7, text: "Sie sagten: \"Wenn du ihnen heute zu Willen bist, wenn du ihnen entgegenkommst und freundlich mit ihnen redest, werden sie dir für immer gehorchen.\"" },
      { number: 8, text: "Doch er verwarf den Rat der Alten und fragte die jungen Leute, die mit ihm aufgewachsen waren und jetzt in seinem Dienst standen." },
      { number: 9, text: "\"Was ratet ihr mir? Was sollen wir diesem Volk sagen, das von mir verlangt hat, das Joch zu erleichtern, das mein Vater auf sie gelegt hat?\"" },
      { number: 10, text: "Da sagten ihm die jungen Leute, die mit ihm aufgewachsen waren: \"Dem Volk, das von dir verlangt, das schwere Joch zu erleichtern, das dein Vater ihm auferlegt hat, sollst du sagen: 'Mein kleiner Finger ist dicker als die Hüften meines Vaters!" },
      { number: 11, text: "Mein Vater hat euch eine schwere Last aufgeladen, ich werde sie noch schwerer machen! Mein Vater hat euch mit Peitschen gezüchtigt, ich werde es mit Stachelpeitschen tun!'\"" },
      { number: 12, text: "Am dritten Tag kamen Jerobeam und das ganze Volk wieder zu Rehabeam, wie der König ihnen gesagt hatte." },
      { number: 13, text: "König Rehabeam gab ihnen eine harte Antwort. Er verwarf die Empfehlung der Alten" },
      { number: 14, text: "und richtete sich nach dem Rat der jungen Leute. Er sagte: \"Mein Vater hat euch eine schwere Last aufgeladen, ich werde sie noch schwerer machen! Mein Vater hat euch mit Peitschen gezüchtigt, ich werde es mit Stachelpeitschen tun!\"" },
      { number: 15, text: "Der König hörte also nicht auf das Volk. Jahwe hatte es so gefügt, um das Wort wahr zu machen, das er, Jahwe, durch Ahija von Schilo zu Jerobeam Ben-Nebat gesprochen hatte." },
      { number: 16, text: "Als nun die Männer Israels sahen, dass der König nicht auf sie hören wollte, riefen sie:\"Was geht uns Davids Sippe an? / Isais Sohn gehört nicht zu uns! / Auf, nach Hause, Israel! / Mag Davids Sippe doch sehen, wo sie bleibt!\"So löste sich die Versammlung auf und jeder ging nach Hause." },
      { number: 17, text: "Rehabeam blieb nur über die Israeliten König, die in den Städten Judas wohnten." },
      { number: 18, text: "Als König Rehabeam dann auch noch Hadoram, den Beauftragten für die Zwangsarbeit, hinschickte, steinigten ihn die Israeliten zu Tode. Der König selbst konnte sich gerade noch auf seinen Wagen retten und nach Jerusalem entkommen." },
      { number: 19, text: "So sagten sich die Nordstämme Israels vom Königshaus David los und sind bis zum heutigen Tag von ihnen getrennt." },
      { number: 20, text: "Als es sich in Israel herumgesprochen hatte, dass Jerobeam zurückgekehrt war, ließen ihn die Nordstämme in ihre Volksversammlung rufen und machten ihn zu ihrem König. Nur der Stamm Juda hielt sich noch zum Königshaus Davids.", heading: "Jerobeam wird König von Israel" },
      { number: 21, text: "Als Rehabeam in Jerusalem angekommen war, stellte er aus den Stämmen Juda und Benjamin ein Heer von 180.000 Soldaten zusammen. Sie sollten gegen Israel kämpfen, um die Königsherrschaft für Rehabeam zurück zu erobern." },
      { number: 22, text: "Da kam das Wort Jahwes zu einem Mann Gottes namens Schemaja:" },
      { number: 23, text: "\"Sag zu Rehabeam Ben-Salomo, dem König von Juda, und zu dem Rest des Volkes in Juda und Benjamin:" },
      { number: 24, text: "'So spricht Jahwe: Zieht nicht los! Kämpft nicht gegen eure Brüder! Kehrt allesamt nach Hause zurück! Ich selbst habe es so gefügt.'\" Da gehorchten sie den Worten Jahwes, kehrten um und gingen nach Hause." },
      { number: 25, text: "Jerobeam baute Sichem im Bergland von Efraïm aus und machte es zu seiner Residenz. Später ließ er auch Pnuël* ausbauen.", heading: "Jerobeams falscher Gottesdienst", footnotes: ["Pnuël. Strategisch bedeutende Stadt im Ostjordanland an einer Furt des Jabbok."] },
      { number: 26, text: "Aber er fürchtete, dass das Königtum doch wieder an die Nachkommen Davids zurückfallen könnte." },
      { number: 27, text: "\"Wenn das Volk regelmäßig nach Jerusalem zieht\", dachte er, \"und dort im Haus Jahwes Opferfeste feiert, dann werden sich die Leute bald wieder ihrem früheren Herrn, dem König von Juda, zuwenden und Rehabeam als ihren König anerkennen. Mich werden sie umbringen und sich Rehabeam unterstellen.\"" },
      { number: 28, text: "So beschloss er, zwei Stierkälber aus Gold anfertigen zu lassen. Zum Volk sagte er: \"Ihr müsst nicht länger nach Jerusalem gehen. Hier sind deine Götter, Israel, die dich aus Ägypten herausgeführt haben!\"" },
      { number: 29, text: "Das eine Stierkalb ließ er in Bet-El* aufstellen, das andere in Dan*.", footnotes: ["Bet-El (Haus Gottes). Jakob hatte hier einen Altar gebaut, siehe 1. Mose 35,1-15. Der Ort lag etwa 19 Kilometer nördlich von Jerusalem auf dem Gebirge Efraïm, der südlichste Punkt des Nordreiches.", "Dan. Die Stadt lag ganz im Norden des Landes in der Nähe des Berges Hermon."] },
      { number: 30, text: "Doch diese Sache wurde zur Sünde. Die Leute nahmen sogar den Weg nach Dan auf sich, um ein Kalb anzubeten." },
      { number: 31, text: "Jerobeam ließ auch ein Höhenheiligtum bauen und setzte Priester aus dem Volk ein, die nicht zum Stamm Levi gehörten." },
      { number: 32, text: "Dann richtete er ein Fest ein, das am 15. November* stattfinden und dem Laubhüttenfest in Jerusalem entsprechen sollte. Dabei stieg er in Bet-El auf den Altar, um seinem Kalb zu opfern. Die Priester, die er eingesetzt hatte, wirkten dabei mit.", footnotes: ["November. Wörtlich: des 8. Monats. Zum Datum siehe unter \"Schaltmonat\" im Vorwort des Übersetzers."] },
      { number: 33, text: "Am 15. November, dem Tag, den er eigenmächtig festgesetzt hatte, veranstaltete Jerobeam ein Fest für die Israeliten. Dazu stieg er auf den Altar, den er in Bet-El aufgestellt hatte, um ein Räucheropfer darzubringen." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Noch während Jerobeam auf dem Altar stand, kam ein Mann Gottes aus Juda, der von Jahwe geschickt worden war.", heading: "Der Gottesmann aus Juda" },
      { number: 2, text: "Im Auftrag Jahwes rief er zum Altar hin: \"Altar! Altar! So spricht Jahwe: 'Pass auf! Ein Sohn wird dem Königshaus David geboren werden mit Namen Joschija. Der wird die Priester schlachten, die auf dir Opfer gebracht haben, und wird Menschenknochen auf dir verbrennen lassen!'\"" },
      { number: 3, text: "Gleichzeitig kündigte er ein Wunderzeichen an und rief: \"Als Zeichen dafür, dass Jahwe gesprochen hat, wird der Altar zerbersten und die Asche darauf verschüttet werden.\"" },
      { number: 4, text: "Als König Jerobeam noch auf dem Altar stehend das hörte, streckte er die Hand aus und rief: \"Packt ihn!\" Im gleichen Augenblick wurde sein Arm steif, dass er die Hand nicht mehr zurückziehen konnte." },
      { number: 5, text: "Der Altar zerbarst und die Asche darauf wurde verschüttet, wie der Mann Gottes es angekündigt hatte." },
      { number: 6, text: "Da bat der König den Mann Gottes: \"Besänftige doch Jahwe, deinen Gott, und bete für mich, dass ich meine Hand wieder zurückziehen kann.\" Der Mann Gottes tat es und der König konnte seine Hand wieder benutzen wie vorher." },
      { number: 7, text: "Dann sagte der König zu dem Mann Gottes: \"Komm doch mit mir ins Haus und stärke dich! Ich möchte dir auch ein Geschenk mitgeben.\"" },
      { number: 8, text: "Doch dieser erwiderte dem König: \"Selbst wenn du mir die Hälfte deines Besitzes geben würdest, käme ich nicht mit. Ich werde hier an diesem Ort weder essen noch trinken." },
      { number: 9, text: "Denn Jahwe hat mir befohlen: 'Du darfst dort nichts essen und nichts trinken und auch nicht auf dem Weg zurückgehen, auf dem du hingehst!'\"" },
      { number: 10, text: "So verließ er Bet-El auf einem anderen Weg, als er gekommen war." },
      { number: 11, text: "Nun wohnte in Bet-El ein alter Prophet. Dessen Söhne kamen heim und erzählten, was der Mann Gottes aus Juda getan und was er zum König gesagt hatte." },
      { number: 12, text: "\"Welchen Weg ist er gegangen?\", fragte ihr Vater. Seine Söhne hatten beobachtet, welchen Weg der Mann Gottes eingeschlagen hatte, und sagten es ihm." },
      { number: 13, text: "Da sagte er: \"Sattelt mir den Esel!\" Dann stieg er auf" },
      { number: 14, text: "und folgte dem Mann Gottes. Er fand ihn unter einer Terebinthe* sitzend. \"Bist du der Mann Gottes aus Juda?\", fragte er ihn. \"Ja\", sagte dieser.", footnotes: ["Terebinthe. Belaubter Baum mit breitem Wipfel, der nicht mehr als 7 m hoch wird und als Schattenspender geschätzt wird."] },
      { number: 15, text: "\"Komm mit in mein Haus und iss etwas!\", bat er ihn dann." },
      { number: 16, text: "Doch er erwiderte: \"Ich darf nicht mit dir umkehren. Ich darf hier an diesem Ort nichts essen und nichts trinken." },
      { number: 17, text: "Denn Jahwe hat mir das ausdrücklich befohlen und außerdem gesagt, dass ich auf einem anderen Weg nach Hause zurückkehren soll.\"" },
      { number: 18, text: "Da sagte der Alte zu ihm: \"Ich bin auch ein Prophet wie du, und ein Engel hat mir im Auftrag Jahwes gesagt: 'Bring ihn mit nach Hause und gib ihm zu essen und zu trinken.'\" Doch das war gelogen." },
      { number: 19, text: "Da kehrte der Mann Gottes mit ihm zurück und aß und trank bei ihm." },
      { number: 20, text: "Während sie zu Tisch saßen, kam das Wort Jahwes zu dem Propheten, der den Mann Gottes aus Juda zurückgeholt hatte." },
      { number: 21, text: "Er rief seinem Gast zu: \"So spricht Jahwe: 'Weil du gegen den Befehl Jahwes gehandelt und das Gebot übertreten hast, das dir Jahwe, dein Gott, auferlegte," },
      { number: 22, text: "weil du umgekehrt bist und an diesem Ort gegessen und getrunken hast, obwohl er dir gesagt hat: Du sollst weder essen noch trinken! Deshalb wird deine Leiche nicht ins Grab deiner Vorfahren kommen!'\"" },
      { number: 23, text: "Nach der Mahlzeit sattelte man für ihn den Esel des Propheten, der ihn zurückgebracht hatte." },
      { number: 24, text: "Er zog fort; doch unterwegs fiel ihn ein Löwe an und tötete ihn. Seine Leiche lag am Weg und der Esel stand daneben. Auch der Löwe blieb neben dem Toten stehen." },
      { number: 25, text: "Die Männer, die vorbeikamen, sahen den Toten am Weg liegen und den Löwen daneben stehen. Sie erzählten es in der Stadt, in der der alte Prophet lebte." },
      { number: 26, text: "Als der es hörte, sagte er: \"Das ist der Mann Gottes, der gegen den Befehl Jahwes gehandelt hat. Darum hat Jahwe ihn dem Löwen preisgegeben. Der hat ihn zerrissen und getötet, wie Jahwe es angekündigt hatte.\"" },
      { number: 27, text: "Dann befahl er seinen Söhnen, ihm einen Esel zu satteln," },
      { number: 28, text: "und ritt zu der Stelle, wo die Leiche auf dem Weg lag. Esel und Löwe standen neben dem Toten. Der Löwe hatte den Toten nicht gefressen und den Esel nicht zerrissen." },
      { number: 29, text: "Da hob der alte Prophet die Leiche des Gottesmannes auf den Esel und brachte ihn zurück in seine Stadt, um ihn zu betrauern und zu bestatten." },
      { number: 30, text: "Er legte ihn in seine eigene Grabkammer und ließ die Totenklage \"Ach, mein Bruder!\" über ihn anstimmen." },
      { number: 31, text: "Nachdem er ihn so begraben hatte, sagte er zu seinen Söhnen: \"Wenn ich gestorben bin, legt mich in dasselbe Grab, in dem der Gottesmann liegt! Lasst meine Gebeine neben seinen ruhen!" },
      { number: 32, text: "Denn was er im Auftrag Jahwes gegen den Altar in Bet-El und alle Opferhöhen in den Städten Samarias gesagt hat, wird gewiss eintreffen.\"" },
      { number: 33, text: "Jerobeam ließ sich durch diese Vorfälle nicht von seinem bösen Weg abbringen, sondern setzte weiterhin Leute aus dem gesamten Volk als Priester für die Opferhöhen ein. Wer Lust hatte, den weihte er zu einem Höhenpriester." },
      { number: 34, text: "Diese Sache wurde zur Sünde für das Haus Jerobeams. Es führte zu seiner Vernichtung und zur Auslöschung seiner Familie." },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Damals wurde Abija, der Sohn Jerobeams, krank.", heading: "Ahijas Weissagung gegen Jerobeam" },
      { number: 2, text: "Da sagte Jerobeam zu seiner Frau: \"Verkleide dich, damit dich niemand als Königin erkennt, und geh nach Schilo* zu dem Propheten Ahija. Er hat mir einst verkündet, dass ich König über dieses Volk werden soll.", footnotes: ["Schilo. Religiöses Zentrum im Hügelland von Efraïm, 32 km nördlich von Jerusalem."] },
      { number: 3, text: "Nimm zehn Brote, einen Kuchen und einen Krug Honig mit. Der Prophet wird dir sagen, was mit dem Jungen geschieht.\"" },
      { number: 4, text: "Jerobeams Frau ging nach Schilo und kam in das Haus von Ahija. Der Prophet konnte sie nicht sehen, weil er altersblind geworden war." },
      { number: 5, text: "Doch Jahwe hatte zu Ahija gesagt: \"Pass auf! Die Frau Jerobeams wird hereinkommen. Sie will Auskunft über ihren kranken Sohn haben. Doch wird sie sich dir nicht zu erkennen geben. Das und das sollst du ihr sagen.\"" },
      { number: 6, text: "Als Ahija hörte, wie sie zur Tür hereinkam, sagte er: \"Komm nur herein, du Ehefrau Jerobeams! Weshalb hast du dich unkenntlich gemacht? Ich habe eine harte Botschaft für dich." },
      { number: 7, text: "Geh heim und sag zu Jerobeam: 'So spricht Jahwe, Israels Gott: Ich habe dich mitten aus dem Volk erhoben und dir die Herrschaft über mein Volk Israel gegeben." },
      { number: 8, text: "Ich habe das Königtum von den Nachkommen Davids weggerissen und es dir übertragen. Aber du bist nicht so wie mein Diener David gewesen, der meine Gebote hielt, mir mit ganzem Herzen folgte und nur das tat, was mir gefällt." },
      { number: 9, text: "Du hast es noch schlimmer getrieben als irgendjemand vor dir. Du hast dir andere Götter gemacht, Gussbilder, und hast mich dadurch verworfen und zum Zorn gereizt." },
      { number: 10, text: "Deshalb werde ich Unglück über das Haus Jerobeams bringen und aus seiner Familie jeden Wandpisser* beseitigen, egal ob er gebunden oder frei* ist. Ich fege die Nachkommen Jerobeams weg, wie man Kotballen wegfegt, bis nichts mehr da ist.", footnotes: ["Wandpisser. Das ist ein bewusst verächtlicher Ausdruck.", "gebunden und frei. Wörtlich: \"den Festgehaltenen und Losgelassenen in Israel\". Das war offenbar ein Pauschalausdruck für alle Arten und Klassen von Menschen. Speziell könnte es Unmündige und Mündige meinen oder Sklaven und Freie."] },
      { number: 11, text: "Wer von ihnen in der Stadt stirbt, den werden die Hunde fressen, und wer auf dem freien Feld stirbt, den werden die Vögel fressen, denn Jahwe hat es gesagt.'" },
      { number: 12, text: "Und du, geh jetzt wieder nach Hause. Sobald du die Stadt betrittst, wird der Junge sterben." },
      { number: 13, text: "Ganz Israel wird ihn betrauern und beklagen. Man wird ihn bestatten, und er wird der Einzige aus der Familie Jerobeams sein, der in ein Grab kommt. Denn er ist der Einzige, in dem sich etwas Gutes in Bezug auf Jahwe, den Gott Israels, fand." },
      { number: 14, text: "Jahwe wird einen König über Israel einsetzen, der die Nachkommen Jerobeams beseitigen wird. Schon heute beginnt sich das zu erfüllen." },
      { number: 15, text: "Jahwe wird Israel einen solchen Schlag versetzen, dass es wie ein Schilfrohr im Wasser schwankt. Er wird Israel aus diesem guten Land, das er ihren Vorfahren gegeben hat, herausreißen und es wegschleudern bis über den Euphrat hinaus. Denn sie haben sich Aschera-Pfähle* gemacht und Jahwe damit erzürnt.", footnotes: ["Die Aschera war eine Fruchtbarkeitsgöttin, die in handlichen Figuren, geweihten Bäumen oder Pfählen verehrt wurde."] },
      { number: 16, text: "Wegen der Sünden, die Jerobeam begangen hat, und mit denen er Israel zur Sünde verführte, wird Jahwe Israel preisgeben.\"" },
      { number: 17, text: "Jerobeams Frau kehrte in ihr Haus nach Tirza* zurück. Gerade, als sie über die Schwelle trat, starb der Junge.", footnotes: ["Tirza lag 9 Kilometer östlich von Samaria und war bis zur Zeit von König Omri die Hauptstadt des Nordreichs, wahrscheinlich das heutige Tell-el-far'ah."] },
      { number: 18, text: "Man bestattete ihn und ganz Israel betrauerte und beklagte ihn, wie es Jahwe durch seinen Diener, den Propheten Ahija, gesagt hatte." },
      { number: 19, text: "Was sonst noch über Jerobeam zu sagen ist, wie er Kriege geführt und geherrscht hat, steht in der Chronik* der Könige von Israel.", heading: "Jerobeams Tod", footnotes: ["Chronik. Oder: Jahrbüchern, Annalen."] },
      { number: 20, text: "Er regierte 22 Jahre*. Dann starb er, und sein Sohn Nadab trat die Herrschaft an seiner Stelle an.", footnotes: ["regierte 22 Jahre. 930-909 v.Chr."] },
      { number: 21, text: "Rehabeam Ben-Salomo regierte über Juda. Er war 41 Jahre alt, als er König wurde, und regierte 17 Jahre* in Jerusalem, der Stadt, die Jahwe aus allen Stämmen Israels erwählt hatte, um seinen Namen dort wohnen zu lassen. Seine Mutter hieß Naama; sie war eine Ammoniterin.", heading: "König Rehabeam von Juda", footnotes: ["regierte 17 Jahre. 931-913 v.Chr."] },
      { number: 22, text: "Auch die Leute von Juda taten, was Jahwe missfiel. Durch die Sünden, die sie begingen, reizten sie ihn zur Eifersucht. Sie trieben es noch schlimmer als ihre Väter." },
      { number: 23, text: "Denn auch sie bauten sich Opferhöhen und stellten geweihte Steinmale und Aschera-Pfähle auf jedem hohen Hügel und unter jedem üppigen Baum auf." },
      { number: 24, text: "Es gab sogar männliche Prostituierte für den Fruchtbarkeitskult. In allem folgten sie den abscheulichen Bräuchen der Völker, die Jahwe vor den Israeliten vertrieben hatte." },
      { number: 25, text: "Im fünften Regierungsjahr Rehabeams* zog König Schischak* von Ägypten gegen Jerusalem.", footnotes: ["fünften ... Rehabeams. 925 v.Chr.", "Schischak wird gewöhnlich mit Pharao Scheschonk I. identifiziert, was aber auf schwerwiegende Probleme stößt, wenn man den Feldzugsbericht des Pharaos mit den biblischen Angaben vergleicht. Neuerdings wird eine Revision der ägyptischen Chronologie diskutiert. Der entsprechende Pharao wäre dann vielleicht Ramses II., der angibt, in seinem 8. Regierungsjahr Jerusalem geplündert zu haben."] },
      { number: 26, text: "Er raubte die Schätze aus dem Haus Jahwes und dem Königspalast. Auch die goldenen Schilde, die Salomo hatte anfertigen lassen, nahm er mit." },
      { number: 27, text: "An deren Stelle ließ König Rehabeam Bronzeschilde anfertigen, die er dem Kommandanten der Leibwache übergab, die am Eingang des Palastes stationiert war." },
      { number: 28, text: "Jedes Mal, wenn der König in das Haus Jahwes ging, trugen seine Leibwächter die Schilde und brachten sie anschließend wieder in ihre Unterkunft zurück." },
      { number: 29, text: "Was sonst noch über Rehabeam und seine Taten zu sagen ist, steht in der Chronik der Könige von Juda." },
      { number: 30, text: "Die Auseinandersetzungen zwischen Rehabeam und Jerobeam dauerten an, solange sie lebten." },
      { number: 31, text: "Als Rehabeam gestorben war, bestattete man ihn in der Davidsstadt. Seine Mutter war die Ammoniterin Naama. Sein Sohn Abija trat die Herrschaft an." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Im 18. Regierungsjahr des Königs Jerobeam Ben-Nebat trat Abija die Herrschaft über Juda an.", heading: "König Abija von Juda" },
      { number: 2, text: "Er regierte drei Jahre lang in Jerusalem. Seine Mutter hieß Maacha und war die Tochter Abischaloms*.", footnotes: ["Abischalom ist eine Variante des Namens Abschalom. Maacha war offenbar die Enkelin Abschaloms und stammte aus der Ehe zwischen Tamar, der Tochter Abschaloms (2. Samuel 14,27) und Uriël (2. Chronik 13,2)."] },
      { number: 3, text: "Er folgte in allem den Sünden seines Vaters. Sein Herz war nicht ungeteilt Jahwe, seinem Gott, ergeben wie das Herz seines Vorfahren David." },
      { number: 4, text: "Doch David zuliebe gab Jahwe ihm einen Thronfolger in Jerusalem, indem er seinen Sohn König werden und Jerusalem bestehen ließ." },
      { number: 5, text: "Denn David hatte Zeit seines Lebens getan, was Jahwe gefiel, und ihm in allen Dingen gehorcht – außer in der Sache mit Urija, dem Hetiter*.", footnotes: ["Urija, dem Hetiter. Siehe 2. Samuel 11."] },
      { number: 6, text: "Solange Abija lebte, hatte Krieg zwischen Rehabeam und Jerobeam geherrscht." },
      { number: 7, text: "Auch zwischen Abija und Jerobeam war Krieg. Was sonst noch über Abija und seine Taten zu sagen ist, findet man in der Chronik der Könige von Juda." },
      { number: 8, text: "Als Abija starb, bestattete man ihn in der Davidsstadt und sein Sohn Asa trat die Herrschaft an." },
      { number: 9, text: "Im 20. Regierungsjahr des Königs Jerobeam von Israel wurde Asa König über Juda.", heading: "König Asa von Juda" },
      { number: 10, text: "Er regierte 41 Jahre lang in Jerusalem. Seine Großmutter hieß Maacha und war die Tochter Abischaloms*.", footnotes: ["Abischaloms. Siehe Fußnote zu Vers 2."] },
      { number: 11, text: "Asa tat wie sein Vorfahr David, was recht vor Jahwe war." },
      { number: 12, text: "Er schaffte alle Männer, die sich für den Fruchtbarkeitskult prostituiert hatten, aus dem Land, und beseitigte auch diese Mistgötzen*, die seine Väter aufgestellt hatten.", footnotes: ["Mistgötzen. Wörtlich: Mistkugel, eine bewusst verächtliche Bezeichnung für die Götzenbilder."] },
      { number: 13, text: "Selbst seine Großmutter Maacha entfernte er aus ihrer Stellung als Königsmutter, weil sie der Aschera ein abscheuliches Götzenbild gemacht hatte. Er ließ dieses Götzenbild in Stücke hauen und im Kidrontal verbrennen." },
      { number: 14, text: "Nur die Opferhöhen ließ er weiter bestehen. Doch sein Leben lang war sein Herz ganz bei Jahwe." },
      { number: 15, text: "Das Gold und Silber und die Gegenstände, die sein Vater Gott geweiht hatte, brachte er ins Haus Jahwes, dazu auch seine eigenen geweihten Gaben." },
      { number: 16, text: "Zwischen Asa und König Bascha von Israel herrschte Krieg, solange sie lebten." },
      { number: 17, text: "So rückte Bascha gegen Juda vor und baute die Stadt Rama* zur Festung aus, um die Wege von und nach Juda kontrollieren zu können.", footnotes: ["Rama liegt nur 8 km nördlich von Jerusalem."] },
      { number: 18, text: "Da schickte Asa Boten mit Gold und Silber aus den Schatzkammern des Tempels und des Königshauses zu Ben-Hadad, dem Sohn Tabrimmons und Enkel Hesjons, dem König von Syrien, nach Damaskus und ließ ihm sagen:" },
      { number: 19, text: "\"Zwischen mir und dir, zwischen meinem und deinem Vater soll ein Bündnis sein! Darum habe ich dir Silber und Gold geschickt. Brich deinen Bund mit König Bascha von Israel, damit er von meiner Grenze abzieht!\"" },
      { number: 20, text: "Ben-Hadad ging darauf ein und schickte seine Heerführer gegen Israels Städte. Sie verwüsteten die Städte Ijon, Dan und Abel-Bet-Maacha*, die Gegend um Kinneret* und das ganze Land des Stammes Naftali.", footnotes: ["Ijon ... Abel-Bet-Maacha. Das sind drei Orte ganz im Norden Israels. Abel-Bet-Maacha ist auch unter dem Namen Abel-Majim bekannt.", "Kinneret. Früherer Name des Sees Gennesaret und einer Ortschaft an seinem Westufer."] },
      { number: 21, text: "Als Bascha das erfuhr, brach er den Ausbau von Rama ab und blieb in Tirza." },
      { number: 22, text: "König Asa bot alle Männer von Juda auf. Sie mussten die Steine und das Bauholz, das Bascha verwenden wollte, aus Rama abtransportieren. Asa ließ damit die Städte Geba in Benjamin und Mizpa* befestigen.", footnotes: ["Geba ... Mizpa. Die Städte liegen ganz in der Nähe Ramas."] },
      { number: 23, text: "Was es sonst noch über Asa und seine Machttaten zu berichten gibt und die Städte, die er gebaut hat, findet man in der Chronik der Könige von Juda. Doch im Alter erkrankte Asa an einem Fußleiden." },
      { number: 24, text: "Als er starb, wurde er in der Grabstätte seiner Vorfahren in der Davidsstadt bestattet und sein Sohn Joschafat trat die Herrschaft an." },
      { number: 25, text: "Im zweiten Regierungsjahr des Königs Asa von Juda wurde Nadab Ben-Jerobeam König über Israel.", heading: "König Nadab von Israel" },
      { number: 26, text: "Er tat, was Jahwe missfiel, und folgte dem bösen Beispiel seines Vaters. Er hielt an den sündhaften Gottesdiensten fest, mit denen dieser Israel verführt hatte." },
      { number: 27, text: "Da zettelte Bascha Ben-Ahija aus dem Stamm Issachar eine Verschwörung gegen ihn an und erschlug ihn bei Gibbeton. Nadab belagerte mit Israel nämlich gerade Gibbeton*, das den Philistern gehörte.", footnotes: ["Gibbeton lag zwischen Jerusalem und Joppe und war vermutlich schon in der Richterzeit den Philistern in die Hände gefallen."] },
      { number: 28, text: "Es war im dritten Regierungsjahr* des Königs Asa von Juda, als Bascha ihn tötete und sein Nachfolger wurde.", footnotes: ["dritten Regierungsjahr. 908 v.Chr."] },
      { number: 29, text: "Sobald er die Herrschaft angetreten hatte, beseitigte er die ganze Familie Jerobeams. Keinen einzigen von seinen Nachkommen ließ er am Leben. So erfüllte sich das Wort Jahwes, das durch Ahija von Schilo verkündigt worden war." },
      { number: 30, text: "Das geschah wegen Jerobeams sündhaften Gottesdiensten, mit denen er Israel zur Sünde verführt und den Zorn Jahwes herausgefordert hatte." },
      { number: 31, text: "Was es sonst noch von Nadab und seinem Tun zu berichten gibt, findet man in der Chronik der Könige von Israel." },
      { number: 32, text: "Zwischen Asa und König Bascha von Israel herrschte Krieg, solange sie lebten." },
      { number: 33, text: "Im dritten Regierungsjahr des Königs Asa von Juda wurde Bascha Ben-Ahija König über ganz Israel. 24 Jahre lang regierte er von Tirza aus", heading: "König Bascha von Israel" },
      { number: 34, text: "und tat, was Jahwe missfiel. Er folgte dem bösen Beispiel Jerobeams und hielt an den sündhaften Gottesdiensten fest, mit denen dieser Israel verführt hatte." },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Da kam das Wort Jahwes zu Jehu Ben-Hanani. Er musste Bascha ausrichten:" },
      { number: 2, text: "\"Ich habe dich aus dem Staub erhoben und zum Führer meines Volkes Israel gemacht. Aber du bist trotzdem Jerobeams bösem Beispiel gefolgt und hast mein Volk Israel zur Sünde verführt, sodass sie mich durch ihr Sündigen zum Zorn gereizt haben." },
      { number: 3, text: "Pass auf! Jetzt werde ich hinter Bascha und seiner Familie genauso ausfegen, wie ich es hinter Jerobeams Familie getan habe." },
      { number: 4, text: "Wer von ihnen in der Stadt stirbt, den werden die Hunde fressen, und wer auf dem freien Feld stirbt, den werden die Vögel fressen.\"" },
      { number: 5, text: "Was es sonst noch von Bascha und seinen Machttaten zu sagen gibt, findet man in der Chronik der Könige Israels." },
      { number: 6, text: "Als er starb, wurde er in Tirza begraben. Sein Sohn Ela wurde sein Nachfolger." },
      { number: 7, text: "Durch den Propheten Jehu Ben-Hanani war das Wort Jahwes an Bascha und seine Familie ergangen, weil er getan hatte, was Jahwe missfiel, und ihn durch seine Taten ebenso wie die Familie Jerobeams zum Zorn reizte und auch deshalb, weil er Jerobeams Nachkommen erschlagen hatte." },
      { number: 8, text: "Im 26. Regierungsjahr des Königs Asa von Juda wurde Ela Ben-Bascha König über Israel. Er regierte zwei Jahre lang in Tirza.", heading: "König Ela von Israel" },
      { number: 9, text: "Dann zettelte Simri, der Befehlshaber über die Hälfte seiner Streitwagen, eine Verschwörung gegen ihn an. Ela hatte gerade im Haus seines Palastvorstehers Arza gezecht und war schon betrunken," },
      { number: 10, text: "als Simri hereinkam und ihn erschlug. Das geschah im 27. Regierungsjahr des Königs Asa von Juda. So wurde Simri Elas Nachfolger." },
      { number: 11, text: "Als er die Macht in den Händen hatte, erschlug er die ganze Familie Baschas. Weder von seinen Verwandten noch von seinen Freunden ließ er einen Wandpisser übrig." },
      { number: 12, text: "So löschte Simri das Haus Baschas aus, wie es Jahwe Bascha durch den Propheten Jehu angekündigt hatte." },
      { number: 13, text: "Das geschah wegen Baschas sündhaften Gottesdiensten und denen seines Sohnes Ela, mit denen sie Israel zur Sünde verführt und den Zorn Jahwes, des Gottes Israels, durch ihre nichtigen Götzen herausgefordert hatten." },
      { number: 14, text: "Was es sonst noch von Ela und seinem Tun zu berichten gibt, findet man in der Chronik der Könige von Israel." },
      { number: 15, text: "Im 27. Regierungsjahr des Königs Asa von Juda wurde Simri für sieben Tage König in Tirza, während das Heer Israels immer noch die Philisterstadt Gibbeton belagerte.", heading: "König Simri von Israel" },
      { number: 16, text: "Als im Heerlager bekannt wurde, dass Simri eine Verschwörung angezettelt und den König erschlagen hatte, riefen die Männer Israels noch am selben Tag ihren Heerführer Omri zum König aus." },
      { number: 17, text: "Omri zog mit dem Heer Israels von Gibbeton nach Tirza und begann die Stadt zu belagern." },
      { number: 18, text: "Als Simri sah, dass die Stadt bezwungen wurde, zog er sich in den Palast des Königshauses zurück. Er ließ das ganze Königshaus über sich anzünden und fand in den Flammen den Tod." },
      { number: 19, text: "Das geschah wegen seiner Sünden, und weil er getan hatte, was Jahwe missfiel, indem er dem bösen Beispiel Jerobeams und seinen sündhaften Gottesdiensten folgte, mit denen er Israel zur Sünde verführt hatte." },
      { number: 20, text: "Was es sonst noch von Simri und seiner Verschwörung zu sagen gibt, findet man in der Chronik der Könige von Israel." },
      { number: 21, text: "Damals hielt jedoch nur ein Teil des Volkes Israel zu Omri. Der andere Teil wollte Tibni Ben-Ginat zum König machen.", heading: "König Omri von Israel" },
      { number: 22, text: "Doch die Anhänger Omris waren stärker als die von Tibni Ben-Ginat. So musste Tibni sterben, und Omri trat die Herrschaft an." },
      { number: 23, text: "Im 31. Regierungsjahr des Königs Asa von Juda wurde Omri König über Israel und regierte zwölf Jahre, sechs davon in Tirza.*", footnotes: ["zwölf ... Tirza. 885-874 v.Chr."] },
      { number: 24, text: "Danach kaufte er den Berg von Samaria für 70 Kilogramm Silber und baute darauf eine Stadt. Nach dem früheren Besitzer des Berges, einem Mann namens Schemer, nannte er sie Samaria." },
      { number: 25, text: "Auch Omri tat, was Jahwe missfiel. Er trieb es sogar schlimmer als seine Vorgänger." },
      { number: 26, text: "In allem folgte er dem bösen Beispiel von Jerobeam Ben-Nebat, der die Israeliten zur Sünde verführt hatte, sodass sie den Zorn Jahwes durch ihre nichtigen Götzen herausforderten." },
      { number: 27, text: "Was es sonst noch über Omris Taten und Erfolge zu sagen gibt, findet man in der Chronik der Könige von Israel." },
      { number: 28, text: "Als Omri starb, wurde er in Samaria begraben, und sein Sohn Ahab trat die Herrschaft an." },
      { number: 29, text: "Im 38. Regierungsjahr des Königs Asa von Juda wurde Ahab Ben-Omri König über Israel und regierte 22 Jahre* in Samaria.", heading: "König Ahab von Israel", footnotes: ["regierte 22 Jahre. 874-853 v.Chr."] },
      { number: 30, text: "Ahab Ben-Omri trieb es schlimmer als alle seine Vorgänger und tat, was Jahwe missfiel." },
      { number: 31, text: "Nicht genug, dass er an den sündhaften Gottesdiensten von Jerobeam Ben-Nebat festhielt, er heiratete auch noch Isebel, eine Tochter des Sidonierkönigs Etbaal. Er ging sogar so weit, dass er dem Götzen Baal diente und sich vor ihm niederwarf." },
      { number: 32, text: "In Samaria hatte er ein Baalshaus gebaut und errichtete nun noch einen Altar für ihn." },
      { number: 33, text: "Außerdem ließ er eine Aschera aufstellen und tat noch vieles andere, womit er Jahwe, den Gott Israels, schwerer beleidigte als alle Könige Israels vor ihm." },
      { number: 34, text: "In seiner Regierungszeit baute Hiël aus Bet-El die Stadt Jericho wieder auf. Als er die Fundamente legte, kostete ihn das seinen ältesten Sohn Abiram. Und als er die Tore einsetzte, kostete ihn das seinen jüngsten Sohn Segub. So erfüllte sich das Wort Jahwes, das er durch Josua Ben-Nun hatte sagen lassen.*", footnotes: ["So ... lassen. Siehe Josua 6,26."] },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Elija aus Tischbe in Gilead sagte zu Ahab: \"So wahr Jahwe, der Gott Israels, lebt, in dessen Dienst ich stehe: In den nächsten Jahren wird es weder Tau noch Regen geben, bis ich es sage!\"", heading: "Wie Propheten die Götzen bekämpfen (17-22)\nElija am Bach Krit" },
      { number: 2, text: "Darauf kam das Wort Jahwes zu Elija:" },
      { number: 3, text: "\"Geh hinüber ins Ostjordanland und versteck dich am Bach Krit!" },
      { number: 4, text: "Ich habe den Raben befohlen, dich dort mit Nahrung zu versorgen, und aus dem Bach kannst du trinken.\"" },
      { number: 5, text: "Elija gehorchte dem Wort Jahwes, ging auf die andere Jordanseite und hielt sich im Tal des Krit auf." },
      { number: 6, text: "Morgens und abends brachten ihm die Raben Brot und Fleisch. Wasser bekam er aus dem Bach." },
      { number: 7, text: "Einige Zeit später vertrocknete der Bach, weil es im ganzen Land keinen Regen gab." },
      { number: 8, text: "Da kam das Wort Jahwes zu Elija:", heading: "Elija in Zarpat" },
      { number: 9, text: "\"Geh nach Zarpat*, das zu Sidon gehört, und bleib dort. Ich habe einer Witwe in dem Ort befohlen, dich zu versorgen.\"", footnotes: ["Zarpat oder Sarepta (Lukas 4,26) war ein Küstenort zwischen Tyrus und Sidon in der Gegend, von wo aus der Götzendienst jetzt gerade nach Israel gekommen war."] },
      { number: 10, text: "Elija machte sich auf den Weg und ging nach Zarpat. Als er ans Stadttor kam, begegnete ihm eine Witwe, die gerade Holz sammelte. Er sprach sie an und bat: \"Hol mir doch ein wenig Wasser zum Trinken!\"" },
      { number: 11, text: "Als sie ging, um es zu holen, rief er ihr nach: \"Bring doch bitte einen Bissen Brot mit!\"" },
      { number: 12, text: "Da sagte sie: \"So wahr Jahwe, dein Gott, lebt: Ich habe keinen Vorrat mehr, nur noch eine Handvoll Mehl im Topf und ein bisschen Öl im Krug. Ich sammle gerade ein paar Holzstücke auf, um mir und meinem Sohn etwas zuzubereiten. Wenn wir das gegessen haben, bleibt uns nur noch der Tod.\"" },
      { number: 13, text: "Da sagte Elija zu ihr: \"Hab keine Angst, mach nur, was du gesagt hast! Aber back zuerst einen kleinen Brotfladen für mich und bring ihn mir heraus! Den Rest kannst du für dich und deinen Sohn zubereiten." },
      { number: 14, text: "Denn so spricht Jahwe, der Gott Israels: 'Das Mehl im Topf wird nicht ausgehen, und das Öl im Krug wird nicht abnehmen, bis Jahwe wieder Regen gibt.'\"" },
      { number: 15, text: "Da ging sie und machte, was Elija ihr aufgetragen hatte. So hatten sie und Elija und ihr Sohn für viele Tage zu essen." },
      { number: 16, text: "Das Mehl im Topf ging nicht aus und das Öl im Krug nahm nicht ab, wie es Jahwe durch Elija versprochen hatte." },
      { number: 17, text: "Einige Zeit später wurde der Sohn dieser Frau, der Hausherrin, krank. Seine Krankheit verschlimmerte sich immer mehr, sodass er zuletzt nicht mehr atmete." },
      { number: 18, text: "Da sagte sie zu Elija: \"Was willst du eigentlich bei mir, Mann Gottes? Du bist doch nur hergekommen, um meine Sünde aufzudecken und meinen Sohn sterben zu lassen!\"" },
      { number: 19, text: "\"Gib mir deinen Sohn!\", sagte er zu ihr. Er nahm ihr das Kind vom Schoß und brachte es in den Raum auf der Dachterrasse. Dort legte er es auf sein Bett." },
      { number: 20, text: "Dann rief er zu Jahwe und sagte: \"Jahwe, mein Gott, willst du wirklich diese Frau, bei der ich wohne, ins Unglück stürzen, dass du ihren Sohn getötet hast?\"" },
      { number: 21, text: "Dann streckte er sich dreimal über das Kind hin und rief dabei: \"Jahwe, mein Gott, lass doch das Leben dieses Kindes wiederkommen!\"" },
      { number: 22, text: "Jahwe hörte auf Elija und gab dem Kind das Leben zurück. Es wurde wieder lebendig." },
      { number: 23, text: "Da nahm Elija das Kind und brachte es ins Haus hinunter. Er gab es seiner Mutter und sagte: \"Sieh her, dein Sohn lebt!\"" },
      { number: 24, text: "Da sagte die Frau zu Elija: \"Jetzt weiß ich, dass du ein Mann Gottes bist und dass das Wort Jahwes wirklich aus deinem Mund kommt.\"" },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Viele Tage später, im dritten Jahr der Hungersnot, kam das Wort Jahwes zu Elija: \"Geh jetzt und zeig dich Ahab! Ich werde dem Land wieder Regen geben.\"", heading: "Elija stellt sich dem König" },
      { number: 2, text: "Elija machte sich auf den Weg zu Ahab. In Samaria war die Hungersnot besonders schwer." },
      { number: 3, text: "Ahab hatte seinen Palastvorsteher Obadja zu sich rufen lassen. – Obadja war sehr gottesfürchtig." },
      { number: 4, text: "Als Isebel nämlich die Propheten Jahwes ermorden ließ, hatte er hundert von ihnen in zwei Höhlen versteckt und sie mit Brot und Wasser versorgt. –" },
      { number: 5, text: "Ahab hatte zu Obadja gesagt: \"Zieh durchs Land zu allen Wasserquellen und Bächen! Vielleicht findet sich irgendwo noch etwas Gras, dass wir Pferde und Maultiere am Leben erhalten können. Sonst müssen wir einen Teil der Tiere töten.\"" },
      { number: 6, text: "Dann teilten sie das Land unter sich auf und gingen jeder für sich auf die Suche." },
      { number: 7, text: "Als Obadja auf dem Weg war, kam ihm Elija entgegen. Er erkannte ihn und warf sich vor ihm nieder. \"Bist du es wirklich, mein Herr Elija?\", fragte er." },
      { number: 8, text: "\"Ja, ich bin es\", erwiderte dieser. \"Geh jetzt zu deinem Herrn und sag ihm: Elija ist da!\"" },
      { number: 9, text: "\"Was habe ich mir denn zu Schulden kommen lassen\", erwiderte Obadja, \"dass du mich Ahab in die Hand gibst? Er wird mich umbringen." },
      { number: 10, text: "So wahr Jahwe, dein Gott, lebt: Es gibt kein Volk und kein Reich, in dem mein Herr dich nicht suchen ließ. Wenn es hieß: 'Er ist nicht hier', ließ er das Volk oder Reich schwören, dass man dich nicht gefunden habe." },
      { number: 11, text: "Und nun soll ich zu meinem Herrn gehen und sagen: 'Schau, Elija ist da!'" },
      { number: 12, text: "Was ist, wenn der Geist Jahwes dich in der Zwischenzeit an einen Ort bringt, den ich nicht kenne? Ahab wird mich umbringen, wenn er dich nicht findet. Dein Diener fürchtet doch Jahwe von Jugend auf." },
      { number: 13, text: "Ist meinem Herrn nicht berichtet worden, was ich getan habe, als Isebel die Propheten Jahwes umbringen ließ? Hundert Mann von den Propheten habe ich versteckt, je fünfzig in einer Höhle, und habe sie mit Brot und Wasser versorgt." },
      { number: 14, text: "Und nun sagst du: 'Geh zu deinem Herrn und sag ihm, dass Elija da ist!' Er wird mich umbringen.\"" },
      { number: 15, text: "Elija aber sagte: \"So wahr Jahwe, der Allmächtige, lebt, dem ich diene: Heute noch werde ich mich ihm zeigen!\"" },
      { number: 16, text: "Da ging Obadja Ahab entgegen und sagte es ihm." },
      { number: 17, text: "Als Ahab dann Elija erblickte, sagte er zu ihm: \"Bist du das, du Unglücksbringer für Israel?\"" },
      { number: 18, text: "Elija erwiderte: \"Nicht ich habe Israel ins Unglück gebracht, sondern du und deine Familie! Ihr habt die Gebote Jahwes verlassen und seid den Baalen nachgelaufen." },
      { number: 19, text: "Schick jetzt Boten aus und versammle ganz Israel zu mir an den Berg Karmel, auch die 450 Propheten des Baal und die 400 der Aschera, die von Isebel versorgt werden.\"" },
      { number: 20, text: "Da ließ Ahab die Männer Israels und die Propheten zum Berg Karmel kommen." },
      { number: 21, text: "Dann trat Elija vor das Volk und sagte: \"Wie lange hinkt ihr noch auf beiden Seiten? Wenn Jahwe Gott ist, dann folgt ihm allein, wenn es Baal ist, dann folgt nur ihm!\" Aber das Volk zeigte keine Reaktion.", heading: "Elija auf dem Karmel" },
      { number: 22, text: "Da fuhr Elija fort: \"Ich allein bin als Prophet Jahwes übrig geblieben. Die Propheten Baals sind 450 Mann." },
      { number: 23, text: "Bringt zwei junge Stiere her! Sie sollen sich den einen auswählen, ihn zerteilen und die Stücke auf das Holz schichten. Sie dürfen das Holz aber nicht anzünden. Und ich, ich werde den anderen Stier herrichten, ihn auf das Holz schichten und es ebenfalls nicht anzünden." },
      { number: 24, text: "Dann ruft ihr den Namen eures Gottes an! Und ich, ich werde den Namen Jahwes anrufen. Der Gott, der mit Feuer antwortet, ist der wahre Gott.\" Da rief das ganze Volk: \"Das ist gut!\"" },
      { number: 25, text: "Nun sagte Elija zu den Propheten des Baal: \"Wählt euch den einen Stier aus und bereitet ihn zu! Ihr seid ja in der Überzahl. Dann ruft den Namen eures Gottes an! Ihr dürft aber kein Feuer daran legen!\"" },
      { number: 26, text: "So nahmen sie den jungen Stier, den man ihnen übergab, und bereiteten ihn zu. Dann riefen sie den Namen Baals an: \"Baal, höre uns!\" Sie riefen vom Morgen bis zum Mittag. Aber es war kein Laut zu hören, es kam keine Antwort. Dabei hinkten und hüpften sie um ihren Altar." },
      { number: 27, text: "Als es Mittag wurde, machte sich Elija über sie lustig. \"Ruft lauter!\", spottete er. \"Er ist ja ein Gott. Er ist sicher in Gedanken, oder er ist gerade austreten gegangen. Vielleicht ist er auch auf Reisen, oder er schläft gerade, dann sollte er aufwachen!\"" },
      { number: 28, text: "Da schrien sie immer lauter und ritzten sich nach ihrem Brauch mit Schwertern und Lanzen, bis Blut an ihnen herabfloss." },
      { number: 29, text: "Als der Mittag vorüber war, weissagten sie wie Propheten. Das dauerte bis zur Zeit des Abendopfers*. Aber es gab keinen Laut, keine Antwort, kein Aufmerken.", footnotes: ["Zeit des Abendopfers. Wörtlich: \"das Speisopfer darbringt\", das war gegen 15 Uhr."] },
      { number: 30, text: "Da rief Elija dem Volk zu: \"Her zu mir!\" Das Volk trat zu ihm hin. Dann begann er, den niedergerissenen Altar Jahwes wieder aufzubauen." },
      { number: 31, text: "Er nahm zwölf Steine nach der Zahl der Stämme der Söhne Jakobs, an den einst das Wort Jahwes ergangen war: \"Du sollst Israel heißen!\"" },
      { number: 32, text: "Aus diesen Steinen baute er dem Namen Jahwes einen Altar. Rings herum zog er einen Graben, der so breit war, dass man 12 Kilogramm* Getreide dort hätte einsäen können.", footnotes: ["12 Kilogramm. Wörtlich: zwei Maß."] },
      { number: 33, text: "Dann schichtete er das Holz auf, zerteilte den Stier und legte die Stücke auf das Holz." },
      { number: 34, text: "Schließlich ließ er vier Eimer Wasser über das Brandopfer und das Holz gießen. Das ließ er noch einmal tun und noch ein drittes Mal." },
      { number: 35, text: "Das Wasser floss über den Altar und füllte auch den Graben." },
      { number: 36, text: "Um die Zeit des Abendopfers trat Elija vor den Altar und sagte: \"Jahwe, Gott Abrahams, Isaaks und Israels! Heute sollen alle erkennen, dass du Gott in Israel bist und dass ich dein Diener bin und nach deinem Wort all das getan habe." },
      { number: 37, text: "Antworte mir Jahwe, antworte mir, damit dieses Volk erkennt, dass du, Jahwe, allein Gott bist und dass du sie wieder auf den rechten Weg zurückbringen willst.\"" },
      { number: 38, text: "Da kam ein Feuer Jahwes herab und verzehrte das Brandopfer, das Holz, die Steine und die Erde und leckte auch das Wasser im Graben auf." },
      { number: 39, text: "Als das Volk das sah, warfen sich alle nieder, das Gesicht auf dem Boden, und riefen: \"Jahwe, er allein ist Gott! Jahwe, er allein ist Gott!\"" },
      { number: 40, text: "Da sagte Elija zu ihnen: \"Packt die Propheten des Baal! Keiner darf entkommen!\" Sie taten es. Dann ließ Elija sie zum Bach Kischon hinabführen und dort hinrichten." },
      { number: 41, text: "Dann sagte Elija zu Ahab: \"Geh nun hinauf, iss und trink! Denn es rauscht schon, als wollte es reichlich regnen.\"", heading: "Das Ende der Trockenheit" },
      { number: 42, text: "Da ging Ahab zum Essen, Elija aber stieg auf den Gipfel des Karmel, kauerte sich auf den Boden und verbarg sein Gesicht zwischen den Knien." },
      { number: 43, text: "Dann sagte er zu seinem Diener: \"Steig hoch und halte Ausschau in Richtung Meer.\" Der tat es und sagte dann: \"Es ist nichts zu sehen!\" Elija sagte: \"Geh noch einmal!\" Siebenmal schickte er ihn so." },
      { number: 44, text: "Beim siebten Mal meldete er: \"Ich sehe eine Wolke aus dem Meer aufsteigen, so klein wie eine Hand.\" Da sagte Elija: \"Geh zu Ahab und sag: 'Lass anspannen und fahr los, damit du nicht vom Regen überrascht wirst!'\"" },
      { number: 45, text: "Inzwischen war Wind aufgekommen und schwarze Wolken verfinsterten den Himmel. Dann kam ein starker Regenguss herunter. Ahab stieg auf seinen Wagen und fuhr los." },
      { number: 46, text: "Da kam die Kraft Jahwes über Elija. Er band sein Obergewand mit dem Gürtel hoch und lief vor Ahab her bis nach Jesreel.*", footnotes: ["bis nach Jesreel. Das waren etwa 35 Kilometer."] },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Ahab erzählte Isebel alles, was Elija getan und wie er die Propheten mit dem Schwert umgebracht hatte.", heading: "Elija am Horeb" },
      { number: 2, text: "Da schickte Isebel einen Boten zu Elija und ließ ihm ausrichten: \"Die Götter sollen mich strafen, wenn ich morgen um diese Zeit dein Leben nicht einem von ihnen gleich mache.\"" },
      { number: 3, text: "Da packte Elija die Angst und er lief um sein Leben. Als er nach Beerscheba* kam, das zu Juda gehört, ließ er seinen Diener dort zurück", footnotes: ["nach Beerscheba. Das waren mindestens 180 km in südlicher Richtung. Als er in Beerscheba, der südlichsten Stadt Judas ankam, hatte er das Herrschaftsgebiet von Ahab und Isebel lange verlassen."] },
      { number: 4, text: "und ging eine Tagereise weit in die Wüste hinein. Dann setzte er sich unter einen Ginsterstrauch und wünschte sich zu sterben. \"Jetzt ist es genug, Jahwe!\", sagte er. \"Nimm mein Leben von mir! Ich bin auch nicht besser als meine Väter.\"" },
      { number: 5, text: "Dann legte er sich hin und schlief unter dem einsamen Ginsterbusch ein. Da rührte ihn auf einmal ein Engel an und sagte: \"Steh auf und iss!\"" },
      { number: 6, text: "Als Elija sich umschaute, sah er neben seinem Kopf ein Fladenbrot, das auf heißen Steinen gebacken war, und einen Krug Wasser. Er aß und trank und legte sich wieder hin." },
      { number: 7, text: "Doch der Engel Jahwes kam noch einmal und weckte ihn. \"Steh auf und iss!\", sagte er. \"Du hast einen weiten Weg vor dir.\"" },
      { number: 8, text: "Er erhob sich, aß und trank und machte sich auf den Weg. Die Speise gab ihm so viel Kraft, dass er vierzig Tage und Nächte hindurch gehen konnte, bis er zum Gottesberg Horeb* kam.", footnotes: ["Horeb ist ein anderer Name für den Berg Sinai. Er liegt etwa 430 km südlich von Beerscheba."] },
      { number: 9, text: "Er ging in die Höhle dort und legte sich schlafen.Plötzlich kam das Wort Jahwes zu ihm: \"Was machst du hier, Elija?\"" },
      { number: 10, text: "\"Mit ganzem Eifer habe ich mich für Jahwe, den allmächtigen Gott, eingesetzt\", sagte er. \"Die Israeliten haben den Bund mit dir gebrochen, deine Altäre niedergerissen und deine Propheten mit dem Schwert erschlagen. Ich allein bin übrig geblieben, nur ich allein. Und jetzt wollen sie auch mich noch umbringen.\"" },
      { number: 11, text: "Da sagte Jahwe: \"Geh hinaus und stell dich auf den Berg vor mich hin! Pass auf! Jahwe wird an dir vorübergehen.\" Da kam ein heftiger Sturm herauf, der Felsen aus den Bergen riss und vor Jahwe zerschmetterte. Doch Jahwe war nicht im Sturm. Nach dem Sturm bebte die Erde, aber Jahwe war nicht im Beben." },
      { number: 12, text: "Nach dem Erdbeben ein Feuer, doch Jahwe war nicht im Feuer. Nach dem Feuer der Ton eines dahinschwebenden Schweigens." },
      { number: 13, text: "Als Elija das hörte, verhüllte er sein Gesicht mit dem Mantel und stellte sich in den Eingang der Höhle. Da fragte ihn eine Stimme: \"Was tust du hier, Elija?\"" },
      { number: 14, text: "Er sagte: \"Mit ganzem Eifer habe ich mich für Jahwe, den allmächtigen Gott, eingesetzt. Denn die Israeliten haben den Bund mit dir gebrochen, deine Altäre niedergerissen und deine Propheten mit dem Schwert erschlagen. Ich allein bin übrig geblieben, nur ich allein. Und jetzt wollen sie auch mich noch umbringen.\"*", footnotes: ["Wird im Neuen Testament von Paulus zitiert (Römer 11,3)."] },
      { number: 15, text: "Da sagte Jahwe zu ihm: \"Geh den Weg durch die Wüste wieder zurück! Geh bis nach Damaskus und salbe dort Hasaël zum König über Syrien." },
      { number: 16, text: "Dann sollst du Jehu Ben-Nimschi zum König über Israel salben und schließlich Elischa Ben-Schafat aus Abel-Mehola zum Propheten an deiner Stelle." },
      { number: 17, text: "Wer dem Schwert Hasaëls entkommt, den wird Jehu töten, und wer dem Schwert Jehus entkommt, den wird Elischa töten." },
      { number: 18, text: "Ich habe 7000 in Israel übrig gelassen, die sich nicht vor Baal hingekniet und sein Bild nicht geküsst haben.\"*", footnotes: ["Wird im Neuen Testament von Paulus zitiert (Römer 11,4)."] },
      { number: 19, text: "Als Elija von dort weggegangen war, traf er Elischa Ben-Schafat gerade beim Pflügen an. Elf Rindergespanne arbeiteten vor ihm, er selbst führte das zwölfte. Im Vorbeigehen warf Elija ihm seinen Prophetenmantel über.", heading: "Elischas Berufung" },
      { number: 20, text: "Da verließ Elischa sein Gespann und folgte Elija. \"Lass mich doch zum Abschied meinen Vater und meine Mutter küssen\", bat er ihn, \"dann will ich dir folgen.\" – \"Geh nur\", erwiderte Elija, \"ich habe dich ja nicht gezwungen!\"" },
      { number: 21, text: "Da wandte sich Elischa von Elija ab, nahm die beiden Rinder seines Gespanns und schlachtete sie. Mit dem Holz des Geschirrs machte er Feuer, briet das Fleisch und gab es seinen Leuten. Dann machte er sich auf, folgte Elija und diente ihm." },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Ben-Hadad, der König von Syrien, bot seine ganze Heeresmacht auf. Zweiunddreißig Vasallenkönige folgten ihm mit Pferd und Wagen. Er zog vor Samaria, schloss die Stadt ein und bereitete den Angriff vor.", heading: "Ahabs Siege über die Syrer" },
      { number: 2, text: "Dann schickte er Boten in die Stadt zu König Ahab von Israel" },
      { number: 3, text: "und ließ ihm sagen: \"So spricht Ben-Hadad: 'Dein Silber und dein Gold gehören mir, ebenso deine Frauen und deine besten Söhne'\"" },
      { number: 4, text: "Der König von Israel ließ ihm antworten: \"Ich unterwerfe mich dir, mein Herr und König, mit allem, was ich habe.\"" },
      { number: 5, text: "Aber die Boten kamen zurück und sagten: \"So spricht Ben-Hadad: 'Ja, ich habe dir gesagt: Gib mir dein Silber und Gold, deine Frauen und deine Söhne." },
      { number: 6, text: "Pass auf! Morgen um diese Zeit schicke ich meine Leute zu dir. Sie werden deinen Palast und die Paläste deiner Minister gründlich durchsuchen und alles mitnehmen, woran du Freude hast.'\"" },
      { number: 7, text: "Da rief der König von Israel alle Ältesten des Landes zu sich und sagte zu ihnen: \"Ihr seht ja, dass dieser Syrer nur Böses will. Ich habe ihm nichts verweigert, weder meine Frauen und Söhne noch mein Silber und Gold.\"" },
      { number: 8, text: "Da riefen ihm die Ältesten und alles Volk zu: \"Hör nicht auf ihn! Geh nicht darauf ein!\"" },
      { number: 9, text: "So gab er den Boten Ben-Hadads Bescheid: \"Sagt meinem Herrn und König: 'Alles, was du zuerst von mir verlangt hast, werde ich tun. Aber diese Forderung kann ich nicht erfüllen.'\" Die Boten überbrachten die Antwort." },
      { number: 10, text: "Da ließ Ben-Hadad ihm ausrichten: \"Die Götter sollen mich strafen, wenn der Schutt von Samaria auch nur für die hohlen Hände meiner Soldaten ausreicht!\"" },
      { number: 11, text: "Doch der König von Israel ließ ihm antworten: \"Wer eine Sache beginnt, soll nicht so angeben wie einer, der sie schon erledigt hat!\"" },
      { number: 12, text: "Ben-Hadad zechte gerade im Zeltlager mit den Vasallenkönigen, als ihm die Antwort überbracht wurde. Da befahl er seinen Leuten: \"Rammböcke ansetzen!\" Sie brachten die Mauerbrecher in Stellung." },
      { number: 13, text: "Da trat auf einmal ein Prophet zu König Ahab von Israel und sagte zu ihm: \"Siehst du diese ganze gewaltige Menge? Ich gebe sie heute in deine Hand. Du sollst erkennen, dass ich Jahwe bin.\"" },
      { number: 14, text: "\"Durch wen soll das geschehen?\", fragte Ahab. Er erwiderte: \"So spricht Jahwe: 'Durch die Leute der Provinzstatthalter.'\" – \"Und wer soll den Kampf eröffnen?\" – \"Du!\"" },
      { number: 15, text: "Da ließ er die Leute der Provinzstatthalter antreten. Es waren 232 Mann. Danach musterte er das ganze Volk, alle Israeliten. Es waren 7000 Mann." },
      { number: 16, text: "Gegen Mittag rückten sie aus. Im Zeltlager zechte Ben-Hadad mit den 32 Vasallenkönigen und war schon betrunken." },
      { number: 17, text: "Zuerst waren die Leute der Provinzstatthalter losgezogen. Ben-Hadad hatte Beobachter aufgestellt, die ihm jetzt meldeten: \"Es kommen Männer aus Samaria.\"" },
      { number: 18, text: "Er befahl: \"Wenn sie um Frieden bitten wollen, greift sie lebendig! Wenn sie zum Kampf ausgezogen sind, nehmt sie gefangen!\"" },
      { number: 19, text: "Als die Leute der Provinzstatthalter jedoch herauskamen und hinter ihnen das ganze Heer Israels," },
      { number: 20, text: "machte jeder im Kampf Mann gegen Mann seinen Gegner nieder. Da ergriffen die Syrer die Flucht, und die Israeliten folgten ihnen. König Ben-Hadad von Syrien jedoch entkam auf einem Pferd mit den Reitern." },
      { number: 21, text: "Dann rückte der König von Israel aus und vernichtete die ganze Streitwagenmacht. So brachte er den Syrern eine schwere Niederlage bei." },
      { number: 22, text: "Da kam der Prophet wieder zum König von Israel und sagte: \"Sammle deine Kräfte und überlege gut, was du tun musst, denn im nächsten Frühjahr wird der König von Syrien wieder gegen dich ziehen.\"" },
      { number: 23, text: "Die Ratgeber des syrischen Königs hatten nämlich zu ihrem König gesagt: \"Die Götter Israels sind Berggötter, darum waren sie uns überlegen. Wenn wir in der Ebene gegen sie kämpfen, werden wir sie bestimmt besiegen." },
      { number: 24, text: "Wir raten dir nur, deine Vasallenkönige abzusetzen und sie durch Statthalter zu ersetzen." },
      { number: 25, text: "Stell ein Heer auf, das ebenso groß ist wie das, das du verloren hast, und schaff dir genauso viele Pferde und Streitwagen an, wie du vorher hattest. Dann wollen wir in der Ebene mit ihnen kämpfen und einmal sehen, ob wir ihnen nicht überlegen sind.\" Der König hörte auf sie." },
      { number: 26, text: "Im folgenden Frühjahr musterte er die Syrer und zog mit seinen Truppen nach Afek*, um gegen Israel zu kämpfen.", footnotes: ["Afek meint wahrscheinlich das heutige Afiq, das einige Kilometer östlich des Sees Gennesaret liegt."] },
      { number: 27, text: "Auch die Israeliten wurden gemustert und mit Vorräten versorgt und zogen den Syrern entgegen. Wie zwei kleine Ziegenherden ließen sie sich ihnen gegenüber nieder, während die Syrer das ganze Land bedeckten." },
      { number: 28, text: "Wieder kam der Mann Gottes zum König von Israel und sagte zu ihm: \"So spricht Jahwe: 'Weil die Syrer gesagt haben, Jahwe sei ein Gott der Berge, hätte aber keine Macht in den Tälern, will ich diese ganze gewaltige Menge in deine Hand geben. Ihr sollt erkennen, dass ich Jahwe bin.'\"" },
      { number: 29, text: "Sieben Tage lagen die beiden Heere einander gegenüber, am siebten Tag kam es zum Kampf. Die Israeliten besiegten die Syrer und erschlugen an diesem einen Tag 100.000 Fußsoldaten." },
      { number: 30, text: "Die Überlebenden 27.000 Mann flohen in die Stadt Afek. Da brach die Stadtmauer über ihnen zusammen.Auch Ben-Hadad war in die Stadt geflohen und suchte nach einem sicheren Versteck." },
      { number: 31, text: "Da sagten seine Ratgeber zu ihm: \"Wir haben gehört, dass die Könige Israels milde Könige sind. Lass uns doch den Trauersack anlegen und einen Strick um unseren Hals binden und so zum König von Israel hinausgehen. Vielleicht lässt er dich am Leben.\"", heading: "Ahab verschont seinen Feind" },
      { number: 32, text: "So gürteten die Ratgeber Sackleinwand um, legten einen Strick um den Hals und gingen zum König von Israel. \"Dein Diener Ben-Hadad lässt dir sagen: Lass mich doch bitte am Leben!\", richteten sie ihm aus. \"Lebt er denn noch?\", fragte Ahab. \"Er ist doch mein Bruder!\"" },
      { number: 33, text: "Das nahmen die Männer als gutes Vorzeichen und legten ihn gleich darauf fest: \"Gewiss, Ben-Hadad ist dein Bruder!\" – \"Geht und holt ihn!\", sagte der König. Als Ben-Hadad dann zu ihm herauskam, ließ er ihn zu sich auf den Wagen steigen." },
      { number: 34, text: "Ben-Hadad sagte: \"Ich werde dir die Städte zurückgeben, die mein Vater deinem Vater weggenommen hat. Du kannst auch Handelsgassen* in Damaskus anlegen, wie mein Vater das in Samaria tat. \"Gut\", sagte der König, \"wenn du mir das schwörst, lasse ich dich gehen.\" Er schloss einen Vertrag mit ihm und ließ ihn ziehen.", footnotes: ["Handelsgassen. Offenbar lukrative Privilegien, die mit einer Monopolstellung in bestimmten Handelsbereichen verbunden waren."] },
      { number: 35, text: "Einer von den Prophetenjüngern* sagte zu einem anderen im Auftrag Jahwes: \"Schlage mich!\" Doch der weigerte sich, ihn zu schlagen.", footnotes: ["Prophetenjünger stammten aus Prophetengruppen, die zusammenlebten und von Elija oder Elischa geleitet wurden, siehe 2. Könige 2; 4; 6."] },
      { number: 36, text: "Da sagte er zu ihm: \"Du hast dich dem Befehl Jahwes widersetzt. Pass auf! Wenn du jetzt weggehst, wird ein Löwe dich schlagen.\" Als der andere wegging, fiel ihn ein Löwe an und tötete ihn." },
      { number: 37, text: "Der Prophetenjünger traf einen anderen Mann und sagte zu ihm: \"Schlage mich!\" Der Mann schlug ihn grün und blau." },
      { number: 38, text: "Da stellte sich der Prophet an den Weg, wo er den König treffen konnte. Er hatte sich den Kopf verbunden, sodass man ihn nicht erkannte." },
      { number: 39, text: "Als der König vorüberkam, rief er ihn an und sagte: \"Dein Diener war mitten in den Kampf geraten. Da brachte mir auf einmal jemand einen Gefangenen und sagte: 'Bewach diesen Mann! Sollte er vermisst werden, kostet es dein Leben oder 35 Kilo Silberstücke.'" },
      { number: 40, text: "Während dein Diener nun hier und da zu tun hatte, war der Gefangene auf einmal fort.\" Der König sagte: \"Du hast dir selbst das Urteil gesprochen.\"" },
      { number: 41, text: "Da nahm er schnell die Binde ab, und der König von Israel erkannte, dass es einer der Propheten war." },
      { number: 42, text: "\"So spricht Jahwe\", sagte der Prophet: \"Du hast den Mann freigelassen, auf den ich meinen Bann gelegt hatte*. Deshalb wirst du mit deinem Leben für seins einstehen und mit deinem Volk für sein Volk!\"", footnotes: ["Bann gelegt hatte. Das heißt: Er sollte mit all seinen Gütern vernichtet werden."] },
      { number: 43, text: "Wütend ging der König weiter und kam schlecht gelaunt zu Hause in Samaria an." },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Einige Zeit später passierte Folgendes: Ein Mann namens Nabot, Einwohner der Stadt Jesreel*, besaß dort einen Weinberg. Dieser lag unmittelbar neben einem Haus, das König Ahab aus Samaria gehörte.", heading: "Nabots Weinberg", footnotes: ["Die Stadt Jesreel befindet sich mitten in der sehr fruchtbaren Jesreel-Ebene etwa 40 km nördlich von Samaria."] },
      { number: 2, text: "Eines Tages sagte Ahab zu Nabot: \"Überlass mir doch deinen Weinberg! Er grenzt direkt an mein Haus und ich möchte gern einen Gemüsegarten daraus machen. Ich gebe dir dafür einen besseren Weinberg als den hier oder wenn es dir lieber ist, gebe ich dir den Preis dafür in Silber.\"" },
      { number: 3, text: "Aber Nabot erwiderte: \"Jahwe behüte mich davor, dir das Erbe meiner Vorfahren zu geben!\"" },
      { number: 4, text: "Wütend und schlecht gelaunt, weil dieser Jesreeliter Nabot sich geweigert hatte, ihm das Erbe seiner Vorfahren abzutreten, kam Ahab in sein Haus. Er legte sich auf sein Bett, drehte sich zur Wand und wollte nichts essen." },
      { number: 5, text: "Da kam seine Frau Isebel zu ihm herein und fragte: \"Warum bist du so verstimmt? Warum isst du nichts?\"" },
      { number: 6, text: "Ahab erwiderte: \"Weil dieser Nabot aus Jesreel mir seinen Weinberg nicht geben will. Ich wollte ihn bezahlen oder ihm dafür einen anderen geben. Aber er sagte nur: 'Meinen Weinberg bekommst du nicht!'\"" },
      { number: 7, text: "Da sagte seine Frau Isebel zu ihm: \"Als König von Israel bist du doch der Herr im Land. Steh auf und iss etwas und vergiss deinen Ärger! Ich werde dir Nabots Weinberg schon verschaffen.\"" },
      { number: 8, text: "Dann schrieb sie Briefe im Namen Ahabs und verschloss sie mit seinem Siegel. Sie waren an Nabots Mitbürger, die Ältesten und die Vornehmen in Jesreel gerichtet." },
      { number: 9, text: "In den Briefen hatte sie Folgendes geschrieben: \"Ruft einen Fasttag aus* und lasst Nabot in der Versammlung ganz vorn sitzen.", footnotes: ["ruft ... aus. Ein allgemeines Fasten konnte bei Unglück oder Trauer, aber auch zur Unterstützung einer Bitte oder Aufdeckung einer Schuld angeordnet werden."] },
      { number: 10, text: "Dann setzt ihm zwei gewissenlose Männer gegenüber, die als Zeugen gegen ihn aussagen sollen, dass er Gott und den König gelästert habe. Dann führt ihn vor die Stadt hinaus und steinigt ihn zu Tode.\"" },
      { number: 11, text: "Die Männer der Stadt, die Ältesten und die Vornehmen, die Nabots Mitbürger waren, machten es genauso, wie Isebel es in ihren Briefen verlangt hatte." },
      { number: 12, text: "Sie riefen einen Fasttag aus und ließen Nabot in der Versammlung ganz vorn sitzen." },
      { number: 13, text: "Dann kamen die beiden boshaften und gewissenlosen Männer und setzten sich ihm gegenüber. Vor dem ganzen Volk traten sie als Zeugen gegen Nabot auf und behaupteten: \"Nabot hat Gott und den König gelästert!\" Daraufhin wurde Nabot vor die Stadt geführt und gesteinigt." },
      { number: 14, text: "Die Verantwortlichen ließen Isebel ausrichten: \"Nabot ist tot, er wurde gesteinigt.\"" },
      { number: 15, text: "Als Isebel diese Nachricht erhalten hatte, sagte sie zu Ahab: \"Auf, nimm den Weinberg in Besitz! Dieser Nabot aus Jesreel, der sich geweigert hat, dir seinen Weinberg zu verkaufen, lebt nicht mehr. Er ist tot.\"" },
      { number: 16, text: "Als Ahab das hörte, wollte er den Weinberg Nabots gleich in Besitz nehmen und ging zu ihm hinunter." },
      { number: 17, text: "Da kam das Wort Jahwes zu Elija aus Tischbe:" },
      { number: 18, text: "\"Mach dich auf den Weg und geh Ahab entgegen, dem König von Israel, der in Samaria residiert. Er ist gerade in den Weinberg Nabots hinuntergegangen, um sich ihn anzueignen." },
      { number: 19, text: "Sag zu ihm: 'So spricht Jahwe: Hast du gemordet und schon geerbt? Jahwe sagt dir: Wo die Hunde das Blut Nabots aufgeleckt haben, dort werden sie auch dein Blut auflecken, ja deins.'\"" },
      { number: 20, text: "Als sie sich trafen, sagte Ahab zu Elija: \"Hast du mich gefunden, mein Feind?\" Elija erwiderte: \"Ich musste dich finden, denn du hast dich anstiften lassen, Böses vor Jahwe zu tun. Darum lässt er dir sagen:" },
      { number: 21, text: "'Pass auf! Ich bringe Unheil über dich. Ich werde deine Familie wegfegen. Von deiner Nachkommenschaft werde ich jeden Wandpisser beseitigen, egal ob er gebunden oder frei ist." },
      { number: 22, text: "Weil du mich zum Zorn gereizt und Israel zur Sünde verführt hast, werde ich mit deiner Familie genauso verfahren wie mit der von Jerobeam Ben-Nebat und Bascha Ben-Ahija.'" },
      { number: 23, text: "Und über Isebel lässt Jahwe dir sagen: 'Die Hunde werden sie fressen an der Vormauer von Jesreel.'" },
      { number: 24, text: "Wer von Ahabs Familie in der Stadt stirbt, wird von Hunden gefressen; und wer auf dem freien Feld stirbt, den fressen die Vögel.\"" },
      { number: 25, text: "In der Tat gab es keinen, der sich wie Ahab dazu hergab, Böses vor Jahwe zu tun. Seine Frau Isebel hatte ihn dazu verführt." },
      { number: 26, text: "Was er tat, war überaus verwerflich, denn er lief diesen Mistgötzen* nach genauso wie die Amoriter, die Jahwe vor den Israeliten vertrieben hatte.", footnotes: ["Mistgötzen. Siehe Fußnote zu Kapitel 15,12!"] },
      { number: 27, text: "Als Ahab das hörte, riss er vor Entsetzen sein Obergewand ein*. Dann legte er den Trauersack an und fastete. Er schlief sogar auf Sacktuch und ging bedrückt umher.", footnotes: ["riss ... Gewänder ein. Als Zeichen von Trauer und Entsetzen riss man das Kleidungsstück vom Halsausschnitt an mit einem heftigen Ruck etwa eine Handlänge ein."] },
      { number: 28, text: "Da kam das Wort Jahwes zu Elija aus Tischbe:" },
      { number: 29, text: "\"Hast du gemerkt, dass Ahab sich vor mir gedemütigt hat? Weil er das tat, lasse ich das Unheil noch nicht zu seinen Lebzeiten über sein Haus kommen, sondern erst, wenn sein Sohn König ist.\"" },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Drei Jahre lang verhielten die Syrer sich ruhig. Es gab keinen Krieg zwischen Syrien und Israel.", heading: "Micha gegen Ahabs Propheten" },
      { number: 2, text: "Im dritten Jahr besuchte König Joschafat von Juda den König von Israel." },
      { number: 3, text: "Dieser hatte zu seinen Beratern gesagt: \"Wisst ihr nicht, dass Ramot in Gilead uns gehört? Warum bleiben wir still, anstatt es dem König von Syrien wieder wegzunehmen?\"" },
      { number: 4, text: "Dann fragte er Joschafat: \"Machst du mit, wenn ich Ramot in Gilead angreife?\" – \"Ja, ich mache mit\", erwiderte Joschafat, \"meine Truppen sollen mit deinen gehen und meine Pferde ebenso.\"" },
      { number: 5, text: "Doch dann sagte Joschafat zum König von Israel: \"Du solltest aber zuerst fragen, was Jahwe dazu sagt!\"" },
      { number: 6, text: "Da ließ der König von Israel die Propheten kommen, 400 Mann. Er fragte sie: \"Soll ich in den Kampf gegen Ramot in Gilead ziehen oder soll ich es lassen?\" – \"Zieh hinauf\", erwiderten sie, \"Gott wird es in die Hand des Königs geben!\"" },
      { number: 7, text: "Aber Joschafat sagte: \"Gibt es hier sonst keinen Propheten Jahwes mehr, durch den wir Gott fragen können?\"" },
      { number: 8, text: "\"Es gibt schon einen, durch den man Jahwe befragen kann\", erwiderte der König von Israel, \"aber ich hasse ihn, weil er mir niemals Gutes, sondern immer nur Schlimmes prophezeit. Es ist Micha Ben-Jimla.\" Doch Joschafat erwiderte: \"Der König sage das nicht!\"" },
      { number: 9, text: "Da rief der König von Israel einen Hofbeamten herbei und befahl ihm: \"Schnell, hole Micha Ben-Jimla!\"" },
      { number: 10, text: "Der König von Israel und König Joschafat von Juda saßen im königlichen Gewand auf zwei Thronsesseln, die man für sie auf dem freien Platz am Toreingang von Samaria aufgestellt hatte. Und die Propheten weissagten vor ihnen." },
      { number: 11, text: "Ein gewisser Zidkija Ben-Kenaana hatte sich eiserne Hörner gemacht und rief: \"So spricht Jahwe: 'Damit wirst du die Syrer niederstoßen, bis du sie vernichtet hast!'\"" },
      { number: 12, text: "Die anderen Propheten weissagten ebenso: \"Greif Ramot in Gilead an und führe Israel zum Sieg! Jahwe wird die Stadt in die Hand des Königs geben!\"" },
      { number: 13, text: "Der Bote, der Micha holen sollte, sagte unterwegs zu ihm: \"Hör zu! Die Worte der Propheten sind einstimmig und sprechen für den König. Schließ dich doch ihrem Wort an und sage Gutes!\"" },
      { number: 14, text: "Micha erwiderte: \"So wahr Jahwe lebt, ich sage nur das, was Jahwe mir aufträgt!\"" },
      { number: 15, text: "Als er zum König kam, fragte ihn dieser: \"Micha, sollen wir in den Kampf gegen Ramot in Gilead ziehen oder sollen wir es lassen?\" – \"Zieh nur hin und führe Israel zum Sieg!\", sagte er. \"Jahwe wird es in die Hand des Königs geben.\"" },
      { number: 16, text: "Doch der König entgegnete: \"Wie oft muss ich dich noch beschwören, dass du mir nichts als die Wahrheit im Namen Jahwes verkündest!\"" },
      { number: 17, text: "Da sagte Micha: \"Ich sah ganz Israel über die Berge zerstreut wie Schafe, die keinen Hirten haben. Und Jahwe sagte: 'Sie haben keinen Anführer mehr! Jeder kehre wohlbehalten in sein Haus zurück!'\"" },
      { number: 18, text: "Da sagte der König von Israel zu Joschafat: \"Habe ich dir nicht gesagt, dass er mir nichts Gutes prophezeit, sondern immer nur Schlimmes?\"" },
      { number: 19, text: "Micha fuhr fort: \"Darum hört das Wort Jahwes: Ich sah Jahwe sitzen auf seinem Thron. Das ganze Heer des Himmels stand rechts und links neben ihm." },
      { number: 20, text: "Jahwe fragte: 'Wer ködert Ahab, dass er loszieht und bei Ramot in Gilead fällt?' Der eine sagte dies, der andere das." },
      { number: 21, text: "Zuletzt trat ein Geist vor. Er stellte sich vor Jahwe und sagte: 'Ich werde ihn ködern.' 'Womit?', fragte Jahwe." },
      { number: 22, text: "'Ich werde als Lügengeist aus dem Mund aller seiner Propheten sprechen', erwiderte er. 'Gut, du darfst ihn verführen', sagte er, 'und du wirst es auch schaffen. Geh los und tu es!'" },
      { number: 23, text: "Du siehst also, dass Jahwe deinen Propheten einen Lügengeist eingegeben hat, denn Jahwe hat dein Unheil beschlossen.\"" },
      { number: 24, text: "Da kam Zidkija Ben-Kenaana zu Micha, gab ihm eine Ohrfeige und sagte: \"Auf welche Weise soll der Geist Jahwes mich denn verlassen haben und nur noch mit dir reden?\"" },
      { number: 25, text: "\"Du wirst es ja sehen\", erwiderte Micha, \"und zwar an dem Tag, an dem du von einer Kammer in die andere flüchtest, um dich zu verstecken.\"" },
      { number: 26, text: "Da sagte der König: \"Nehmt ihn fest und führt ihn zum Stadtkommandanten Amon und zum Prinzen Joasch." },
      { number: 27, text: "Meldet ihnen: 'So spricht der König: Setzt diesen Mann ins Gefängnis und haltet ihn knapp bei Brot und Wasser, bis ich wohlbehalten zurückkomme!'\"" },
      { number: 28, text: "Da sagte Micha: \"Wenn du je wohlbehalten zurückkehrst, hat Jahwe nicht durch mich gesprochen.\" Dann fügte er noch hinzu: \"Hört es, ihr Völker alle!\"" },
      { number: 29, text: "Der König von Israel und König Joschafat von Juda zogen also nach Ramot in Gilead.", heading: "Ahabs Tod" },
      { number: 30, text: "Unterwegs sagte der König von Israel zu Joschafat: \"Ich will verkleidet in den Kampf ziehen, aber du kannst deine königliche Kleidung tragen!\" So zog er verkleidet in die Schlacht." },
      { number: 31, text: "Der König von Syrien hatte den zweiunddreißig Führern seiner Streitwagen befohlen: \"Kämpft nicht gegen Kleine oder Große, sondern greift allein den König von Israel an!\"" },
      { number: 32, text: "Als die Streitwagenführer Joschafat entdeckten, sagten sie: \"Das ist der König von Israel!\" und griffen ihn von allen Seiten an. Da schrie Joschafat um Hilfe." },
      { number: 33, text: "Als die Wagenführer merkten, dass er nicht der König von Israel war, ließen sie ihn in Ruhe." },
      { number: 34, text: "Einer ihrer Kämpfer aber schoss auf gut Glück einen Pfeil ab und traf den König von Israel zwischen Gurt und Panzer. \"Dreh um und bring mich aus der Schlacht!\", sagte der König zu seinem Wagenlenker. \"Ich bin verwundet.\"" },
      { number: 35, text: "Weil der Kampf an dem Tag immer heftiger wurde, hielt der König bis zum Abend durch und blieb den Syrern gegenüber in seinem Wagen aufrecht stehen, während das Blut aus seiner Wunde in den Wagen floss. Gegen Abend starb er." },
      { number: 36, text: "Als die Sonne unterging, ließ man im Lager ausrufen: \"Jeder kehre in seine Stadt und auf sein Land zurück!\"" },
      { number: 37, text: "So starb der König. Man brachte ihn nach Samaria und begrub ihn dort." },
      { number: 38, text: "Als man den Wagen am Teich von Samaria abspülte, leckten die Hunde sein Blut auf, und die Huren wuschen sich in dem Wasser, wie Jahwe es angekündigt hatte." },
      { number: 39, text: "Was es sonst noch über Ahab und seine Taten zu berichten gibt, das Elfenbeinhaus und die Städte, die er gebaut hat, findet man in der Chronik der Könige von Israel." },
      { number: 40, text: "Nachdem Ahab gestorben war, trat sein Sohn Ahasja die Herrschaft an." },
      { number: 41, text: "Im 4. Regierungsjahr des Königs Ahab von Israel wurde Joschafat Ben-Asa König über Juda.", heading: "König Joschafat von Juda" },
      { number: 42, text: "Als er die Herrschaft übernahm, war er 35 Jahre alt. Er regierte 25 Jahre in Jerusalem. Seine Mutter hieß Asuba und war eine Tochter von Schilhi." },
      { number: 43, text: "Er folgte in allem konsequent dem Beispiel seines Vaters Asa, indem er tat, was Jahwe gefiel." },
      { number: 44, text: "Nur die Opferhöhen bestanden weiter, und die Leute brachten dort Schlacht- und Räucheropfer dar." },
      { number: 45, text: "Joschafat machte Frieden mit dem König von Israel." },
      { number: 46, text: "Was sonst noch über Joschafat, seine Machttaten und Kriege zu sagen ist, steht in der Chronik der Könige von Juda." },
      { number: 47, text: "Er schaffte auch die Männer, die sich für den Fruchtbarkeitskult prostituiert hatten, aus dem Land, denn es waren noch welche aus der Zeit seines Vaters Asa übrig geblieben." },
      { number: 48, text: "Damals hatte Edom keinen eigenen König. Es wurde von einem Statthalter Judas regiert." },
      { number: 49, text: "Joschafat hatte auch eine Tarschisch-Flotte bauen lassen, die nach Ofir* fahren sollte, um Gold zu holen. Es kam aber nicht dazu, weil die Flotte bei Ezjon-Geber* zerschellte.", footnotes: ["Ofir. Siehe Fußnote zu 2. Chronik 8,18.", "Ezjon-Geber. Hafenstadt am Golf von Elat/Akaba, in der Nähe des heutigen Elat."] },
      { number: 50, text: "König Ahasja Ben-Ahab wollte damals seine Leute auf Joschafats Schiffen mitfahren lassen. Doch Joschafat hatte es abgelehnt." },
      { number: 51, text: "Als Joschafat starb, bestattete man ihn in der Davidsstadt, und sein Sohn Joram trat die Herrschaft an." },
      { number: 52, text: "Im 17. Regierungsjahr des Königs Joschafat von Juda wurde Ahasja Ben-Ahab für zwei Jahre* König über Israel.", heading: "König Ahasja von Israel", footnotes: ["zwei Jahre. 853-852 v.Chr."] },
      { number: 53, text: "Er tat, was Jahwe missfiel, und folgte dem bösen Beispiel seines Vaters und seiner Mutter und hielt auch an den sündhaften Gottesdiensten fest, mit denen Jerobeam Ben-Nebat Israel verführt hatte." },
      { number: 54, text: "Außerdem verehrte er den Baal und warf sich vor ihm nieder. Damit beleidigte er Jahwe, den Gott Israels, genauso, wie sein Vater es getan hatte." },
    ] },
  ],
};